window.__QR["data/core/5.json"]={"v":[["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ","O ye who believe! Fulfil your indentures. The beast of cattle is made lawful unto you (for food) except that which is announced unto you (herein), game being unlawful when ye are on the pilgrimage. Lo! Allah ordaineth that which pleaseth Him"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","O ye who believe! Profane not Allah's monuments nor the Sacred Month nor the offerings nor the garlands, nor those repairing to the Sacred House, seeking the grace and pleasure of their Lord. But when ye have left the sacred territory, then go hunting (if ye will). And let not your hatred of a folk who (once) stopped your going to the inviolable place of worship seduce you to transgress; but help ye one another unto righteousness and pious duty. Help not one another unto sin and transgression, but keep your duty to Allah. Lo! Allah is severe in punishment"],["حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","Forbidden unto you (for food) are carrion and blood and swineflesh, and that which hath been dedicated unto any other than Allah, and the strangled, and the dead through beating, and the dead through falling from a height, and that which hath been killed by (the goring of) horns, and the devoured of wild beasts, saving that which ye make lawful (by the death-stroke), and that which hath been immolated unto idols. And (forbidden is it) that ye swear by the divining arrows. This is an abomination. This day are those who disbelieve in despair of (ever harming) your religion; so fear them not, fear Me! This day have I perfected your religion for you and completed My favour unto you, and have chosen for you as religion al-Islam. Whoso is forced by hunger, not by will, to sin: (for him) lo! Allah is Forgiving, Merciful"],["يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ","They ask thee (O Muhammad) what is made lawful for them. Say: (all) good things are made lawful for you. And those beasts and birds of prey which ye have trained as hounds are trained, ye teach them that which Allah taught you; so eat of that which they catch for you and mention Allah's name upon it, and observe your duty to Allah. Lo! Allah is swift to take account"],["ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ","This day are (all) good things made lawful for you. The food of those who have received the Scripture is lawful for you, and your food is lawful for them. And so are the virtuous women of the believers and the virtuous women of those who received the Scripture before you (lawful for you) when ye give them their marriage portions and live with them in honour, not in fornication, nor taking them as secret concubines. Whoso denieth the faith, his work is vain and he will be among the losers in the Hereafter"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","O ye who believe! When ye rise up for prayer, wash you faces, and your hands up to the elbows, and lightly rub your heads and (wash) your feet up to the ankles. And if ye are unclean, purify yourselves. And if ye are sick or on a journey, or one of you cometh from the closet, or ye have had contact with women, and ye find not water, then go to clean, high ground and rub your faces and your hands with some of it. Allah would not place a burden on you, but He would purify you and would perfect His grace upon you, that ye may give thanks"],["وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","Remember Allah's grace upon you and His covenant by which He bound you when ye said: We hear and we obey; And keep your duty to Allah. Lo! He knoweth what is in the breasts (of men)"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ","O ye who believe! Be steadfast witnesses for Allah in equity, and let not hatred of any people seduce you that ye deal not justly. Deal justly, that is nearer to your duty. Observe your duty to Allah. Lo! Allah is Informed of what ye do"],["وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٞ","Allah hath promised those who believe and do good works: Theirs will be forgiveness and immense reward"],["وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ","And they who disbelieve and deny Our revelations, such are rightful owners of hell"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ","O ye who believe! Remember Allah's favour unto you, how a people were minded to stretch out their hands against you but He withheld their hands from you; and keep your duty to Allah. In Allah let believers put their trust"],["۞وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","Allah made a covenant of old with the Children of Israel and We raised among them twelve chieftains, and Allah said: Lo! I am with you. If ye establish worship and pay the poor-due, and believe in My messengers and support them, and lend unto Allah a kindly loan, surely I shall remit your sins, and surely I shall bring you into Gardens underneath which rivers flow. Whoso among you disbelieveth after this will go astray from a plain road"],["فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّـٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ","And because of their breaking their covenant, We have cursed them and made hard their hearts. They change words from their context and forget a part of that whereof they were admonished. Thou wilt not cease to discover treachery from all save a few of them. But bear with them and pardon them. Lo! Allah loveth the kindly"],["وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ","And with those who say: \"Lo! we are Christians,\" We made a covenant, but they forgot a part of that whereof they were admonished. Therefor We have stirred up enmity and hatred among them till the Day of Resurrection, when Allah will inform them of their handiwork"],["يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ مُّبِينٞ","O People of the Scripture! Now hath Our messenger come unto you, expounding unto you much of that which ye used to hide in the Scripture, and forgiving much. now hath come unto you light from Allah and plain Scripture"],["يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","Whereby Allah guideth him who seeketh His good pleasure unto paths of peace. He bringeth them out of darkness unto light by His decree, and guideth them unto a straight path"],["لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","They indeed have disbelieved who say: Lo! Allah is the Messiah, son of Mary. Say: Who then can do aught against Allah, if He had willed to destroy the Messiah son of Mary, and his mother and everyone on earth? Allah's is the Sovereignty of the heavens and the earth and all that is between them. He createth what He will. And Allah is Able to do all things"],["وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَـٰٓؤُاْ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ","The Jews and Christians say: We are sons of Allah and His loved ones. Say: Why then doth He chastise you for your sins? Nay, ye are but mortals of His creating. He forgiveth whom He will, and chastiseth whom He will. Allah's is the Sovereignty of the heavens and the earth and all that is between them, and unto Him is the journeying"],["يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةٖ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ فَقَدۡ جَآءَكُم بَشِيرٞ وَنَذِيرٞۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","O People of the Scripture! Now hath Our messenger come unto you to make things plain unto you after an interval (of cessation) of the messengers, lest ye should say: There came not unto us a messenger of cheer nor any warner. Now hath a messenger of cheer and a warner come unto you. Allah is Able to do all things"],["وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ","And (remember) when Moses said unto his people: O my people! Remember Allah's favour unto you, how He placed among you prophets, and He made you kings, and gave you that (which) He gave not to any (other) of (His) creatures"],["يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ","O my people! Go into the holy land which Allah hath ordained for you. Turn not in flight, for surely ye turn back as losers"],["قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ","They said: O Moses! Lo! a giant people (dwell) therein and lo! we go not in till they go forth from thence. When they go forth from thence, then we will enter (not till then)"],["قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ","Then out spake two of those who feared (their Lord, men) unto whom Allah had been gracious: Enter in upon them by the gate, for if ye enter by it, lo! ye will be victorious. So put your trust (in Allah) if ye are indeed believers"],["قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ","They said: O Moses! We will never enter (the land) while they are in it. So go thou and thy Lord and fight! We will sit here"],["قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ","He said: My Lord! I have control of none but myself and my brother, so distinguish between us and the wrong-doing folk"],["قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ","(Their Lord) said: For this the land will surely be forbidden them for forty years that they will wander in the earth, bewildered. So grieve not over the wrongdoing folk"],["۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ","But recite unto them with truth the tale of the two sons of Adam, how they offered each a sacrifice, and it was accepted from the one of them and it was not accepted from the other. (The one) said: I will surely kill thee. (The other) answered: Allah accepteth only from those who ward off (evil)"],["لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ","Even if thou stretch out thy hand against me to kill me, I shall not stretch out my hand against thee to kill thee, lo! I fear Allah, the Lord of the Worlds"],["إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ","Lo! I would rather thou shouldst bear the punishment of the sin against me and thine own sin and become one of the owners of the fire. That is the reward of evil-doers"],["فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ","But (the other's) mind imposed on him the killing of his brother, so he slew him and became one of the losers"],["فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِينَ","Then Allah sent a raven scratching up the ground, to show him how to hide his brother's naked corpse. He said: Woe unto me! Am I not able to be as this raven and so hide my brother's naked corpse? And he became repentant"],["مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ","For that cause We decreed for the Children of Israel that whosoever killeth a human being for other than manslaughter or corruption in the earth, it shall be as if he had killed all mankind, and whoso saveth the life of one, it shall be as if he had saved the life of all mankind. Our messengers came unto them of old with clear proofs (of Allah's Sovereignty), but afterwards lo! many of them became prodigals in the earth"],["إِنَّمَا جَزَـٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ","The only reward of those who make war upon Allah and His messenger and strive after corruption in the land will be that they will be killed or crucified, or have their hands and feet on alternate sides cut off, or will be expelled out of the land. Such will be their degradation in the world, and in the Hereafter theirs will be an awful doom"],["إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","Save those who repent before ye overpower them. For know that Allah is Forgiving, Merciful"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ","O ye who believe! Be mindful of your duty to Allah, and seek the way of approach unto Him, and strive in His way in order that ye may succeed"],["إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ","As for those who disbelieve, lo! if all that is in the earth were theirs, and as much again therewith, to ransom them from the doom on the Day of Resurrection, it would not be accepted from them. Theirs will be a painful doom"],["يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ","They will wish to come forth from the Fire, but they will not come forth from it. Theirs will be a lasting doom"],["وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ","As for the thief, both male and female, cut off their hands. It is the reward of their own deeds, an exemplary punishment from Allah. Allah is Mighty, Wise"],["فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","But whoso repenteth after his wrongdoing and amendeth, lo! Allah will relent toward him. Lo! Allah is Forgiving, Merciful"],["أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","Knowest thou not that unto Allah belongeth the Sovereignty of the heavens and the earth? He punisheth whom He will, and forgiveth whom He will. Allah is Able to do all things"],["۞يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ","O Messenger! Let not them grieve thee who vie one with another in the race to disbelief, of such as say with their mouths: \"We believe,\" but their hearts believe not, and of the Jews: listeners for the sake of falsehood, listeners on behalf of other folk who come not unto thee, changing words from their context and saying: If this be given unto you, receive it, but if this be not given unto you, then beware! He whom Allah doometh unto sin, thou (by thine efforts) wilt avail him naught against Allah. Those are they for whom the Will of Allah is that He cleanse not their hearts. Theirs in the world will be ignominy, and in the Hereafter an awful doom"],["سَمَّـٰعُونَ لِلۡكَذِبِ أَكَّـٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـٔٗاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","Listeners for the sake of falsehood! Greedy for illicit gain! If then they have recourse unto thee (Muhammad) judge between them or disclaim jurisdiction. If thou disclaimest jurisdiction, then they cannot harm thee at all. But if thou judgest, judge between them with equity. Lo! Allah loveth the equitable"],["وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ","How come they unto thee for judgment when they have the Torah, wherein Allah hath delivered judgment (for them)? Yet even after that they turn away. Such (folk) are not believers"],["إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ","Lo! We did reveal the Torah, wherein is guidance and a light, by which the prophets who surrendered (unto Allah) judged the Jews, and the rabbis and the priests (judged) by such of Allah's Scripture as they were bidden to observe, and thereunto were they witnesses. So fear not mankind, but fear Me. And My revelations for a little gain. Whoso judgeth not by that which Allah hath revealed: such are disbelievers"],["وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ","And We prescribed for them therein: The life for the life, and the eye for the eye, and the nose for the nose, and the ear for the ear, and the tooth for the tooth, and for wounds retaliation. But whoso forgoeth it (in the way of charity) it shall be expiation for him. Whoso judgeth not by that which Allah hath revealed: such are wrong-doers"],["وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ","And We caused Jesus, son of Mary, to follow in their footsteps, confirming that which was (revealed) before him in the Torah, and We bestowed on him the Gospel wherein is guidance and a light, confirming that which was (revealed) before it in the Torah - a guidance and an admonition unto those who ward off (evil)"],["وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ","Let the People of the Gospel judge by that which Allah hath revealed therein. Whoso judgeth not by that which Allah hath revealed: such are evil-livers"],["وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","And unto thee have We revealed the Scripture with the truth, confirming whatever Scripture was before it, and a watcher over it. So judge between them by that which Allah hath revealed, and follow not their desires away from the truth which hath come unto thee. For each We have appointed a divine law and a traced-out way. Had Allah willed He could have made you one community. But that He may try you by that which He hath given you (He hath made you as ye are). So vie one with another in good works. Unto Allah ye will all return, and He will then inform you of that wherein ye differ"],["وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ","So judge between them by that which Allah hath revealed, and follow not their desires, but beware of them lest they seduce thee from some part of that which Allah hath revealed unto thee. And if they turn away, then know that Allah's Will is to smite them for some sin of theirs. Lo! many of mankind are evil-livers"],["أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ","Is it a judgment of the time of (pagan) ignorance that they are seeking? Who is better than Allah for judgment to a people who have certainty (in their belief)"],["۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ","O ye who believe! Take not the Jews and the Christians for friends. They are friends one to another. He among you who taketh them for friends is (one) of them. Lo! Allah guideth not wrongdoing folk"],["فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ","And thou seest those in whose heart is a disease race toward them, saying: We fear lest a change of fortune befall us. And it may happen that Allah will vouchsafe (unto thee) the victory, or a commandment from His presence. Then will they repent them of their secret thoughts"],["وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ","Then will the believers say (unto the people of the Scripture): are these they who swore by Allah their most binding oaths that they were surely with you? Their works have failed, and they have become the losers"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","O ye who believe! Whoso of you becometh a renegade from his religion, (know that in his stead) Allah will bring a people whom He loveth and who love Him, humble toward believers, stern toward disbelievers, striving in the way of Allah, and fearing not the blame of any blamer. Such is the grace of Allah which He giveth unto whom He will. Allah is All-Embracing, All-Knowing"],["إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ","Your guardian can be only Allah; and His messenger and those who believe, who establish worship and pay the poordue, and bow down (in prayer)"],["وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ","And whoso taketh Allah and His messenger and those who believe for guardian (will know that), lo! the party of Allah, they are the victorious"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ","O Ye who believe! Choose not for guardians such of those who received the Scripture before you, and of the disbelievers, as make a jest and sport of your religion. But keep your duty to Allah if ye are true believers"],["وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ","And when ye call to prayer they take it for a jest and sport. That is because they are a folk who understand not"],["قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ","Say: O People of the Scripture! Do ye blame us for aught else than that we believe in Allah and that which is revealed unto us and that which was revealed aforetime, and because most of you are evil-livers"],["قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ","Shall I tell thee of a worse (case) than theirs for retribution with Allah? (Worse is the case of him) whom Allah hath cursed, him on whom His wrath hath fallen and of whose sort Allah hath turned some to apes and swine, and who serveth idols. Such are in worse plight and further astray from the plain road"],["وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ","When they come unto you (Muslims), they say: We believe; but they came in unbelief and they went out in the same; and Allah knoweth best what they were hiding"],["وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ","And thou seest many of them vying one with another in sin and transgression and their devouring of illicit gain. Verily evil is what they do"],["لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ","Why do not the rabbis and the priests forbid their evil-speaking and their devouring of illicit gain? Verily evil is their handiwork"],["وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ","The Jews say: Allah's hand is fettered. Their hands are fettered and they are accursed for saying so. Nay, but both His hands are spread out wide in bounty. He bestoweth as He will. That which hath been revealed unto thee from thy Lord is certain to increase the contumacy and disbelief of many of them, and We have cast among them enmity and hatred till the Day of Resurrection. As often as they light a fire for war, Allah extinguisheth it. Their effort is for corruption in the land, and Allah loveth not corrupters"],["وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّـٰتِ ٱلنَّعِيمِ","If only the People of the Scripture would believe and ward off (evil), surely We should remit their sins from them and surely We should bring them into Gardens of Delight"],["وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ","If they had observed the Torah and the Gospel and that which was revealed unto them from their Lord, they would surely have been nourished from above them and from beneath their feet. Among them there are people who are moderate, but many of them are of evil conduct"],["۞يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","O Messenger! Make known that which hath been revealed unto thee from thy Lord, for if thou do it not, thou wilt not have conveyed His message. Allah will protect thee from mankind. Lo! Allah guideth not the disbelieving folk"],["قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","Say O People of the Scripture! Ye have naught (of guidance) till ye observe the Torah and the Gospel and that which was revealed unto you from your Lord. That which is revealed unto thee (Muhammad) from thy Lord is certain to increase the contumacy and disbelief of many of them. But grieve not for the disbelieving folk"],["إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","Lo! those who believe, and those who are Jews, and Sabaeans, and Christians - Whosoever believeth in Allah and the Last Day and doeth right - there shall no fear come upon them neither shall they grieve"],["لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ","We made a covenant of old with the Children of Israel and We sent unto them messengers. As often as a messenger came unto them with that which their souls desired not (they became rebellious). Some (of them) they denied and some they slew"],["وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ","They thought no harm would come of it, so they were wilfully blind and deaf. And afterward Allah turned (in mercy) toward them. Now (even after that) are many of them wilfully blind and deaf. Allah is Seer of what they do"],["لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ","They surely disbelieve who say: Lo! Allah is the Messiah, son of Mary. The Messiah (himself) said: O Children of Israel, worship Allah, my Lord and your Lord. Lo! whoso ascribeth partners unto Allah, for him Allah hath forbidden paradise. His abode is the Fire. For evil-doers there will be no helpers"],["لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ إِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ","They surely disbelieve who say: Lo! Allah is the third of three; when there is no Allah save the One Allah. If they desist not from so saying a painful doom will fall on those of them who disbelieve"],["أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","Will they not rather turn unto Allah and seek forgiveness of Him? For Allah is Forgiving, Merciful"],["مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ","The Messiah, son of Mary, was no other than a messenger, messengers (the like of whom) had passed away before him. And his mother was a saintly woman. And they both used to eat (earthly) food. See how We make the revelations clear for them, and see how they are turned away"],["قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","Say: Serve ye in place of Allah that which possesseth for you neither hurt nor use? Allah it is Who is the Hearer, the Knower"],["قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ","Say: O People of the Scripture! Stress not in your religion other than the truth, and follow not the vain desires of folk who erred of old and led many astray, and erred from a plain road"],["لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ","Those of the Children of Israel who went astray were cursed by the tongue of David, and of Jesus, son of Mary. That was because they rebelled and used to transgress"],["كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ","They restrained not one another from the wickedness they did. Verily evil was that they used to do"],["تَرَىٰ كَثِيرٗا مِّنۡهُمۡ يَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ","Thou seest many of them making friends with those who disbelieve. Surely ill for them is that which they themselves send on before them: that Allah will be wroth with them and in the doom they will abide"],["وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ","If they believed in Allah and the Prophet and that which is revealed unto him, they would not choose them for their friends. But many of them are of evil conduct"],["۞لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ","Thou wilt find the most vehement of mankind in hostility to those who believe (to be) the Jews and the idolaters. And thou wilt find the nearest of them in affection to those who believe (to be) those who say: Lo! We are Christians. That is because there are among them priests and monks, and because they are not proud"],["وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ","When they listen to that which hath been revealed unto the messengers, thou seest their eyes overflow with tears because of their recognition of the Truth. They say: Our Lord, we believe. Inscribe us as among the witnesses"],["وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّـٰلِحِينَ","How should we not believe in Allah and that which hath come unto us of the Truth. And (how should we not) hope that our Lord will bring us in along with righteous folk"],["فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ","Allah hath rewarded them for that their saying - Gardens underneath which rivers flow, wherein they will abide for ever. That is the reward of the good"],["وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ","But those who disbelieve and deny Our revelations, they are owners of hell-fire"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ","O ye who believe! Forbid not the good things which Allah hath made lawful for you, and transgress not, Lo! Allah loveth not transgressors"],["وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ","Eat of that which Allah hath bestowed on you as food lawful and good, and keep your duty to Allah in Whom ye are believers"],["لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّـٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّـٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ","Allah will not take you to task for that which is unintentional in your oaths, but He will take you to task for the oaths which ye swear in earnest. The expiation thereof is the feeding of ten of the needy with the average of that wherewith ye feed your own folk, or the clothing of them, or the liberation of a slave, and for him who findeth not (the wherewithal to do so) then a three days' fast. This is the expiation of your oaths when ye have sworn; and keep your oaths. Thus Allah expoundeth unto you His revelations in order that ye may give thanks"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ","O ye who believe! Strong drink and games of chance and idols and divining arrows are only an infamy of Satan's handiwork. Leave it aside in order that ye may succeed"],["إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ","Satan seeketh only to cast among you enmity and hatred by means of strong drink and games of chance, and to turn you from remembrance of Allah and from (His) worship. Will ye then have done"],["وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ","Obey Allah and obey the messenger, and beware! But if ye turn away, then know that the duty of Our messenger is only plain conveyance (of the message)"],["لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","There shall be no sin (imputed) unto those who believe and do good works for what they may have eaten (in the past). So be mindful of your duty (to Allah), and believe, and do good works; and again: be mindful of your duty, and believe; and once again: be mindful of your duty, and do right. Allah loveth the good"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ","O ye who believe! Allah will surely try you somewhat (in the matter) of the game which ye take with your hands and your spears, that Allah may know him who feareth Him in secret. Whoso transgresseth after this, for him there is a painful doom"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ وَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّـٰرَةٞ طَعَامُ مَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ","O ye who believe! Kill no wild game while ye are on the pilgrimage. Whoso of you killeth it of set purpose he shall pay its forfeit in the equivalent of that which he hath killed, of domestic animals, the judge to be two men among you known for justice, (the forfeit) to be brought as an offering to the Ka'bah; or, for expiation, he shall feed poor persons, or the equivalent thereof in fasting, that he may taste the evil consequences of his deed. Allah forgiveth whatever (of this kind) may have happened in the past, but whoso relapseth, Allah will take retribution from him. Allah is Mighty, Able to Requite (the wrong)"],["أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ","To hunt and to eat the fish of the sea is made lawful for you, a provision for you and for seafarers; but to hunt on land is forbidden you so long as ye are on the pilgrimage. Be mindful of your duty to Allah, unto Whom ye will be gathered"],["۞جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَـٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ","Allah hath appointed the Ka'bah, the Sacred House, a standard for mankind, and the Sacred Month and the offerings and the garlands. That is so that ye may know that Allah knoweth whatsoever is in the heavens and whatsoever is in the earth, and that Allah is Knower of all things"],["ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","Know that Allah is severe in punishment, but that Allah (also) is Forgiving, Merciful"],["مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ","The duty of the messenger is only to convey (the message). Allah knoweth what ye proclaim and what ye hide"],["قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ","Say: The evil and the good are not alike even though the plenty of the evil attract thee. So be mindful of your duty to Allah, O men of understanding, that ye may succeed"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ","O ye who believe! Ask not of things which, if they were made unto you, would trouble you; but if ye ask of them when the Qur'an is being revealed, they will be made known unto you. Allah pardoneth this, for Allah is Forgiving, Clement"],["قَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ","A folk before you asked (for such disclosures) and then disbelieved therein"],["مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ","Allah hath not appointed anything in the nature of a Bahirah or a Sa'ibah or a Wasilah or a Hami, but those who disbelieve invent a lie against Allah. Most of them have no sense"],["وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ حَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ","And when it is said unto them: Come unto that which Allah hath revealed and unto the messenger, they say: Enough for us is that wherein we found our fathers. What! Even though their fathers had no knowledge whatsoever, and no guidance"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","O ye who believe! Ye have charge of your own souls. He who erreth cannot injure you if ye are rightly guided. Unto Allah ye will all return; and then He will inform you of what ye used to do"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا عَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ","O ye who believe! Let there be witnesses between you when death draweth nigh unto one of you, at the time of bequest - two witnesses, just men from among you, or two others from another tribe, in case ye are campaigning in the land and the calamity of death befall you. Ye shall empanel them both after the prayer, and, if ye doubt, they shall be made to swear by Allah (saying): We will not take a bribe, even though it were (on behalf of) a near kinsman nor will we hide the testimony of Allah, for then indeed we should be of the sinful"],["فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ","But then, if it is afterwards ascertained that both of them merit (the suspicion of) sin, let two others take their place of those nearly concerned, and let them swear by Allah, (saying): Verily our testimony is truer than their testimony and we have not transgressed (the bounds of duty), for them indeed we should be of the evil-doers"],["ذَٰلِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ أَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ","Thus it is more likely that they will bear true witness or fear that after their oaths the oaths (of others) will be taken. So be mindful of your duty (to Allah) and hearken. Allah guideth not the froward folk"],["۞يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ","In the day when Allah gathereth together the messengers, and saith: What was your response (from mankind)? they say: We have no knowledge. Lo! Thou, only Thou art the Knower of Things Hidden"],["إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَـٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ","When Allah saith: O Jesus, son of Mary! Remember My favour unto thee and unto thy mother; how I strengthened thee with the holy Spirit, so that thou spakest unto mankind in the cradle as in maturity; and how I taught thee the Scripture and Wisdom and the Torah and the Gospel; and how thou didst shape of clay as it were the likeness of a bird by My permission, and didst blow upon it and it was a bird by My permission, and thou didst heal him who was born blind and the leper by My permission; and how thou didst raise the dead by My permission; and how I restrained the Children of Israel from (harming) thee when thou camest unto them with clear proofs, and those of them who disbelieved exclaimed: This is naught else than mere magic"],["وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ","And when I inspired the disciples, (saying): Believe in Me and in My messenger, they said: We believe. Bear witness that we have surrendered (unto Thee) \"we are muslims"],["إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ","When the disciples said: O Jesus, son of Mary! Is thy Lord able to send down for us a table spread with food from heaven? He said: Observe your duty to Allah, if ye are true believers"],["قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّـٰهِدِينَ","(They said:) We wish to eat thereof, that we may satisfy our hearts and know that thou hast spoken truth to us, and that thereof we may be witnesses"],["قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰزِقِينَ","Jesus, son of Mary, said: O Allah, Lord of us! Send down for us a table spread with food from heaven, that it may be a feast for us, for the first of us and for the last of us, and a sign from Thee. Give us sustenance, for Thou art the Best of Sustainers"],["قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ","Allah said: Lo! I send it down for you. And whoso disbelieveth of you afterward, him surely will I punish with a punishment wherewith I have not punished any of (My) creatures"],["وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ","And when Allah saith: O Jesus, son of Mary! Didst thou say unto mankind: Take me and my mother for two gods beside Allah? he saith: Be glorified! It was not mine to utter that to which I had no right. If I used to say it, then Thou knewest it. Thou knowest what is in my mind, and I know not what is in Thy Mind. Lo! Thou, only Thou, art the Knower of Things Hidden"],["مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","I spake unto them only that which Thou commandedst me, (saying): Worship Allah, my Lord and your Lord. I was a witness of them while I dwelt among them, and when Thou tookest me Thou wast the Watcher over them. Thou art Witness over all things"],["إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","If Thou punish them, lo! they are Thy slaves, and if Thou forgive them (lo! they are Thy slaves). Lo! Thou, only Thou, art the Mighty, the Wise"],["قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","Allah saith: This is a day in which their truthfulness profiteth the truthful, for theirs are Gardens underneath which rivers flow, wherein they are secure for ever, Allah taking pleasure in them and they in Him. That is the great triumph"],["لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ","Unto Allah belongeth the Sovereignty of the heavens and the earth and whatsoever is therein, and He is Able to do all things"]],"jal":[[1,1,"سُورَة المائِدَة [ مَدَنِيَّة وآياتها ١٢٠ نَزَلَتْ بَعْد الفَتْح ]\n\n﴿يا أيّها الَّذِينَ آمَنُوا أوْفُوا بِالعُقُودِ﴾ العُهُود المُؤَكَّدَة الَّتِي بَيْنكُمْ وبَيْن اللَّه والنّاس ﴿أُحِلَّتْ لَكُمْ بَهِيمَة الأَنْعام﴾ الإبِل والبَقَر والغَنَم أكْلًا بَعْد الذَّبْح ﴿إلّا ما يُتْلى عَلَيْكُمْ﴾ تَحْرِيمه فِي ﴿حُرِّمَتْ عَلَيْكُمْ المَيْتَة﴾ الآيَة فالِاسْتِثْناء مُنْقَطِع ويَجُوز أنْ يَكُون مُتَّصِلًا والتَّحْرِيم لِما عَرَضَ مِن المَوْت ونَحْوه ﴿غَيْر مُحِلِّي الصَّيْد وأَنْتُمْ حُرُم﴾ أيْ مُحْرِمُونَ ونَصْب غَيْر عَلى الحال مِن ضَمِير لَكُمْ ﴿إنّ اللَّه يَحْكُم ما يُرِيد﴾ مِن التَّحْلِيل وغَيْره لا اعْتِراض عَلَيْهِ"],[2,2,"﴿يا أيّها الَّذِينَ آمَنُوا لا تُحِلُّوا شَعائِر اللَّه﴾ جَمْع شَعِيرَة أيْ مَعالِم دِينه بِالصَّيْدِ فِي الإحْرام ﴿ولا الشَّهْر الحَرام﴾ بِالقِتالِ فِيهِ ﴿ولا الهَدْي﴾ ما أُهْدِيَ إلى الحَرَم مِن النِّعَم بِالتَّعَرُّضِ لَهُ ﴿ولا القَلائِد﴾ جَمْع قِلادَة وهِيَ ما كانَ يُقَلَّد بِهِ مِن شَجَر الحَرَم لِيَأْمَن أيْ فَلا تَتَعَرَّضُوا لَها ولا لِأَصْحابِها ﴿ولا﴾ تُحِلُّوا ﴿آمِّينَ﴾ قاصِدِينَ ﴿البَيْت الحَرام﴾ بِأَنْ تُقاتِلُوهُمْ ﴿يَبْتَغُونَ فَضْلًا﴾ رِزْقًا ﴿مِن رَبّهمْ﴾ بِالتِّجارَةِ ﴿ورِضْوانًا﴾ مِنهُ بِقَصْدِهِ بِزَعْمِهِمْ الفاسِد وهَذا مَنسُوخ بِآيَةِ بَراءَة ﴿وإذا حَلَلْتُمْ﴾ مِن الإحْرام ﴿فاصْطادُوا﴾ أمْر إباحَة ﴿ولا يَجْرِمَنكُمْ﴾ يَكْسِبَنكُمْ ﴿شَنَآن﴾ بِفَتْحِ النُّون وسُكُونها بُغْض ﴿قَوْم﴾ لِأَجْلِ ﴿أنْ صَدُّوكُمْ عَنْ المَسْجِد الحَرام أنْ تَعْتَدُوا﴾ عَلَيْهِمْ بِالقَتْلِ وغَيْره ﴿وتَعاوَنُوا عَلى البِرّ﴾ بِفِعْلِ ما أُمِرْتُمْ بِهِ ﴿والتَّقْوى﴾ بِتَرْكِ ما نُهِيتُمْ عَنْهُ ﴿ولا تَعاوَنُوا﴾ فِيهِ حَذْف إحْدى التّاءَيْنِ فِي الأَصْل ﴿عَلى الإثْم﴾ المَعاصِي ﴿والعُدْوان﴾ التَّعَدِّي فِي حُدُود اللَّه ﴿واتَّقُوا اللَّه﴾ خافُوا عِقابه بِأَنْ تُطِيعُوهُ ﴿إنّ اللَّه شَدِيد العِقاب﴾ لِمَن خالَفَهُ"],[3,3,"﴿حُرِّمَتْ عَلَيْكُمْ المَيْتَة﴾ أيْ أكْلها ﴿والدَّم﴾ أيْ المَسْفُوح كَما فِي الأَنْعام ﴿ولَحْم الخِنْزِير وما أُهِلَّ لِغَيْرِ اللَّه بِهِ﴾ بِأَنْ ذُبِحَ عَلى اسْم غَيْره ﴿والمُنْخَنِقَة﴾ المَيْتَة خَنْقًا ﴿والمَوْقُوذَة﴾ المَقْتُولَة ضَرْبًا ﴿والمُتَرَدِّيَة﴾ السّاقِطَة مِن عُلْو إلى أسْفَل فَماتَتْ ﴿والنَّطِيحَة﴾ المَقْتُولَة بِنَطْحِ أُخْرى لَها ﴿وما أكَلَ السَّبُع﴾ مِنهُ ﴿إلّا ما ذَكَّيْتُمْ﴾ أيْ أدْرَكْتُمْ فِيهِ الرُّوح مِن هَذِهِ الأَشْياء فَذَبَحْتُمُوهُ ﴿وما ذُبِحَ عَلى﴾ اسْم ﴿النُّصُب﴾ جَمْع نِصاب وهِيَ الأَصْنام ﴿وأَنْ تَسْتَقْسِمُوا﴾ تَطْلُبُوا القَسْم والحُكْم ﴿بِالأَزْلامِ﴾ جَمْع زَلَم بِفَتْحِ الزّاي وضَمّها مَعَ فَتْح اللّام قِدْح بِكَسْرِ القاف صَغِير لا رِيش لَهُ ولا نَصْل وكانَتْ سَبْعَة عِنْد سادِن الكَعْبَة. عَلَيْها أعْلام وكانُوا يَحْكُمُونَها فَإنْ أمَرَتْهُمْ ائْتَمَرُوا وإنْ نَهَتْهُمْ انْتَهَوْا ﴿ذَلِكُمْ فِسْق﴾ خُرُوج عَنْ الطّاعَة ونَزَلَ يَوْم عَرَفَة عام حَجَّة الوَداع ﴿اليَوْم يَئِسَ الَّذِينَ كَفَرُوا مِن دِينكُمْ﴾ أنْ تَرْتَدُّوا عَنْهُ بَعْد طَمَعهمْ فِي ذَلِك لِما رَأَوْا مِن قُوَّته ﴿فَلا تَخْشَوْهُمْ واخْشَوْنِي اليَوْم أكْمَلْت لَكُمْ دِينكُمْ﴾ أحْكامه وفَرائِضه فَلَمْ يَنْزِل بَعْدها حَلال ولا حَرام ﴿وأَتْمَمْت عَلَيْكُمْ نِعْمَتِي﴾ بِإكْمالِهِ وقِيلَ بِدُخُولِ مَكَّة آمِنِينَ ﴿ورَضِيت﴾ أيْ اخْتَرْت ﴿لَكُمْ الإسْلام دِينًا فَمَن اُضْطُرَّ فِي مَخْمَصَة﴾ مَجاعَة إلى أيّ شَيْء مِمّا حُرِّمَ عَلَيْهِ فَأَكَلَهُ ﴿غَيْر مُتَجانِف﴾ مائِل ﴿لِإثْمٍ﴾ مَعْصِيَة ﴿فَإنَّ اللَّه غَفُور﴾ لَهُ ما أكَلَ ﴿رَحِيم﴾ بِهِ فِي إباحَته بِخِلافِ المائِل لِإثْمٍ أيْ المُتَلَبِّس بِهِ كَقاطِعِ الطَّرِيق والباغِي مَثَلًا فَلا يَحِلّ لَهُ الأَكْل"],[4,4,"﴿يَسْأَلُونَك﴾ يا مُحَمَّد ﴿ماذا أُحِلَّ لَهُمْ﴾ مِن الطَّعام ﴿قُلْ أُحِلَّ لَكُمْ الطَّيِّبات﴾ المُسْتَلَذّات ﴿و﴾ صَيْد ﴿ما عَلَّمْتُمْ مِن الجَوارِح﴾ الكَواسِب مِن الكِلاب والسِّباع والطَّيْر ﴿مُكَلِّبِينَ﴾ حال مِن كَلَّبْت الكَلْب بِالتَّشْدِيدِ أيْ أرْسَلْته عَلى الصَّيْد ﴿تُعَلِّمُونَهُنَّ﴾ حال مِن ضَمِير مُكَلِّبِينَ أيْ تُؤَدِّبُونَهُنَّ ﴿مِمّا عَلَّمَكُمْ اللَّه﴾ مِن آداب الصَّيْد ﴿فَكُلُوا مِمّا أمْسَكْنَ عَلَيْكُمْ﴾ وإنْ قَتَلَتْهُ بِأَنْ لَمْ يَأْكُلْنَ مِنهُ بِخِلافِ غَيْر المُعَلَّمَة فَلا يَحِلّ صَيْدها وعَلامَتها أنْ تَسْتَرْسِل إذا أُرْسِلَتْ وتَنْزَجِر إذا زُجِرَتْ وتُمْسِك الصَّيْد ولا تَأْكُل مِنهُ وأَقَلّ ما يُعْرَف بِهِ ثَلاث مَرّات فَإنْ أكَلَتْ مِنهُ فَلَيْسَ مِمّا أمْسَكْنَ عَلى صاحِبها فَلا يَحِلّ أكْله كَما فِي حَدِيث الصَّحِيحَيْنِ وفِيهِ أنَّ صَيْد السَّهْم إذا أُرْسِلَ وذُكِرَ اسْم اللَّه عَلَيْهِ كَصَيْدِ المُعَلَّم مِن الجَوارِح ﴿واذْكُرُوا اسْم اللَّه عَلَيْهِ﴾ عِنْد إرْساله"],[5,5,"﴿اليَوْم أُحِلَّ لَكُمْ الطَّيِّبات﴾ المُسْتَلَذّات ﴿وطَعام الَّذِينَ أُوتُوا الكِتاب﴾ أيْ ذَبائِح اليَهُود والنَّصارى ﴿حِلّ﴾ حَلال ﴿لَكُمْ وطَعامكُمْ﴾ إيّاهُمْ ﴿حِلّ لَهُمْ والمُحْصَنات مِن والمُؤْمِنات والمُحْصَنات﴾ الحَرائِر ﴿مِن الَّذِينَ أُوتُوا الكِتاب مِن قَبْلكُمْ﴾ حِلّ لَكُمْ أنْ تَنْكِحُوهُنَّ ﴿إذا آتَيْتُمُوهُنَّ أُجُورهنَّ﴾ مُهُورهنَّ ﴿مُحْصِنِينَ﴾ مُتَزَوِّجِينَ ﴿غَيْر مُسافِحِينَ﴾ مُعْلِنِينَ بِالزِّنا بِهِنَّ ﴿ولا مُتَّخِذِي أخْدان﴾ مِنهُنَّ تُسِرُّونَ بِالزِّنا بِهِنَّ ﴿ومَن يَكْفُر بِالإيمانِ﴾ أيْ يَرْتَدّ ﴿فَقَدْ حَبِطَ عَمَله﴾ الصّالِح قَبْل ذَلِك فَلا يُعْتَدّ بِهِ ولا يُثاب عَلَيْهِ ﴿وهُوَ فِي الآخِرَة مِن الخاسِرِينَ﴾ إذا ماتَ عَلَيْهِ"],[6,6,"﴿يا أيّها الَّذِينَ آمَنُوا إذا قُمْتُمْ﴾ أيْ أرَدْتُمْ القِيام ﴿إلى الصَّلاة﴾ وأَنْتُمْ مُحْدِثُونَ ﴿فاغْسِلُوا وُجُوهكُمْ وأَيْدِيكُمْ إلى المَرافِق﴾ أيْ مَعَها كَما بَيَّنَتْهُ السُّنَّة. ﴿وامْسَحُوا بِرُءُوسِكُمْ﴾ الباء لِلْإلْصاقِ أيْ ألْصِقُوا المَسْح بِها مِن غَيْر إسالَة ماء وهُوَ اسْم جِنْس فَيَكْفِي أقَلّ ما يَصْدُق عَلَيْهِ وهُوَ مَسْح بَعْض شَعْره وعَلَيْهِ الشّافِعِيّ ﴿وأَرْجُلكُمْ﴾ بِالنَّصْبِ عَطْفًا عَلى أيْدِيكُمْ وبِالجَرِّ عَلى الجِوار ﴿إلى الكَعْبَيْنِ﴾ أيْ مَعَهُما كَما بَيَّنَتْهُ السُّنَّة وهُما العَظْمانِ النّاتِئانِ فِي كُلّ رِجْل عِنْد مَفْصِل السّاق والقَدَم والفَصْل بَيْن الأَيْدِي والأَرْجُل المَغْسُولَة بِالرَّأْسِ المَمْسُوح يُفِيد وُجُوب التَّرْتِيب فِي طَهارَة هَذِهِ الأَعْضاء وعَلَيْهِ الشّافِعِيّ ويُؤْخَذ مِن السُّنَّة وُجُوب النِّيَّة فِيهِ كَغَيْرِهِ مِن العِبادات ﴿وإنْ كُنْتُمْ جُنُبًا فاطَّهَّرُوا﴾ فاغْتَسِلُوا ﴿وإنْ كُنْتُمْ مَرْضى﴾ مَرَضًا يَضُرّهُ الماء ﴿أوْ عَلى سَفَر﴾ أيْ مُسافِرِينَ ﴿أوْ جاءَ أحَد مِنكُمْ مِن الغائِط﴾ أيْ أحْدَثَ ﴿أوْ لامَسْتُمْ النِّساء﴾ سَبَقَ مِثْله فِي آيَة النِّساء ﴿فَلَمْ تَجِدُوا ماء﴾ بَعْد طَلَبه ﴿فَتَيَمَّمُوا﴾ اقْصِدُوا ﴿صَعِيدًا طَيِّبًا﴾ تُرابًا طاهِرًا ﴿فامْسَحُوا بِوُجُوهِكُمْ وأَيْدِيكُمْ﴾ مَعَ المِرْفَقَيْنِ ﴿مِنهُ﴾ بِضَرْبَتَيْنِ والباء لِلْإلْصاقِ وبَيَّنَتْ السُّنَّة أنَّ المُراد اسْتِيعاب العُضْوَيْنِ بِالمَسْحِ ﴿ما يُرِيد اللَّه لِيَجْعَل عَلَيْكُمْ مِن حَرَج﴾ ضِيق بِما فَرَضَ عَلَيْكُمْ مِن الوُضُوء والغُسْل والتَّيَمُّم ﴿ولَكِنْ يُرِيد لِيُطَهِّركُمْ﴾ مِن الأَحْداث والذُّنُوب ﴿ولِيُتِمّ نِعْمَته عَلَيْكُمْ﴾ بِالإسْلامِ بِبَيانِ شَرائِع الدِّين ﴿لَعَلَّكُمْ تَشْكُرُونَ﴾ نِعَمه"],[7,7,"﴿واذْكُرُوا نِعْمَة اللَّه عَلَيْكُمْ﴾ بِالإسْلامِ ﴿ومِيثاقه﴾ عَهْده ﴿الَّذِي واثَقَكُمْ بِهِ﴾ عاهَدَكُمْ عَلَيْهِ ﴿إذْ قُلْتُمْ﴾ لِلنَّبِيِّ ﷺ حِين بايَعْتُمُوهُ ﴿سَمِعْنا وأَطَعْنا﴾ فِي كُلّ ما تَأْمُر بِهِ وتَنْهى مِمّا نُحِبّ ونَكْرَه ﴿واتَّقُوا اللَّه﴾ فِي مِيثاقه أنْ تَنْقُضُوهُ ﴿إنّ اللَّه عَلِيم بِذاتِ الصُّدُور﴾ بِما فِي القُلُوب فَبِغَيْرِهِ أوْلى"],[8,8,"﴿يا أيّها الَّذِينَ آمَنُوا كُونُوا قَوّامِينَ﴾ قائِمِينَ ﴿لِلَّهِ﴾ بِحُقُوقِهِ ﴿شُهَداء بِالقِسْطِ﴾ بِالعَدْلِ ﴿ولا يَجْرِمَنكُمْ﴾ يَحْمِلَنكُمْ ﴿شَنَآن﴾ بُغْض ﴿قَوْم﴾ أيْ الكُفّار ﴿عَلى ألّا تَعْدِلُوا﴾ فَتَنالُوا مِنهُمْ لِعَداوَتِهِمْ ﴿اعْدِلُوا﴾ فِي العَدُوّ والوَلِيّ ﴿هُوَ﴾ أيْ العَدْل ﴿أقْرَب لِلتَّقْوى واتَّقُوا اللَّه إنّ اللَّه خَبِير بِما تَعْمَلُونَ﴾ فَيُجازِيكُمْ بِهِ"],[9,9,"﴿وعَدَ اللَّه الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحات﴾ وعْدًا حَسَنًا ﴿لَهُمْ مَغْفِرَة وأَجْر عَظِيم﴾ هُوَ الجَنَّة"],[11,11,"﴿يا أيّها الَّذِينَ آمَنُوا اُذْكُرُوا نِعْمَتْ اللَّه عَلَيْكُمْ إذْ هَمَّ قَوْم﴾ هُمْ قُرَيْش ﴿أنْ يَبْسُطُوا﴾ يَمُدُّوا ﴿إلَيْكُمْ أيْدِيهمْ﴾ لِيَفْتِكُوا بِكُمْ ﴿فَكَفَّ أيْدِيهمْ عَنْكُمْ﴾ وعَصَمَكُمْ مِمّا أرادُوا بِكُمْ"],[12,12,"﴿ولَقَدْ أخَذَ اللَّه مِيثاق بَنِي إسْرائِيل﴾ بِما يُذْكَر بَعْد ﴿وبَعَثْنا﴾ فِيهِ التِفات عَنْ الغَيْبَة أقَمْنا ﴿مِنهُمْ اثْنَيْ عَشَرَ نَقِيبًا﴾ مِن كُلّ سَبْط نَقِيب يَكُون كَفِيلًا عَلى قَوْمه بِالوَفاءِ بِالعَهْدِ تَوْثِقَةً عَلَيْهِمْ ﴿وقالَ﴾ لَهُمْ ﴿اللَّه إنِّي مَعَكُمْ﴾ بِالعَوْنِ والنُّصْرَة ﴿لَئِنْ﴾ لام قَسَم ﴿أقَمْتُمْ الصَّلاة وآتَيْتُمْ الزَّكاة وآمَنتُمْ بِرُسُلِي وعَزَّرْتُمُوهُمْ﴾ نَصَرْتُمُوهُمْ ﴿وأَقْرَضْتُمْ اللَّه قَرْضًا حَسَنًا﴾ بِالإنْفاقِ فِي سَبِيله ﴿لَأُكَفِّرَن عَنْكُمْ سَيِّئاتكُمْ ولَأُدْخِلَنكُمْ جَنّات تَجْرِي مِن تَحْتها الأَنْهار فَمَن كَفَرَ بَعْد ذَلِكَ﴾ المِيثاق ﴿مِنكُمْ فَقَدْ ضَلَّ سَواء السَّبِيل﴾ أخْطَأَ طَرِيق الحَقّ، والسَّواء فِي الأَصْل الوَسَط فَنَقَضُوا المِيثاق"],[13,13,"﴿فَبِما نَقْضِهِمْ﴾ ما زائِدَة ﴿مِيثاقهمْ لَعَنّاهُمْ﴾ أبْعَدْناهُمْ عَنْ رَحْمَتنا ﴿وجَعَلْنا قُلُوبهمْ قاسِيَة﴾ لا تَلِين لِقَبُولِ الإيمان ﴿يُحَرِّفُونَ الكَلِم﴾ الَّذِي فِي التَّوْراة مِن نَعْت مُحَمَّد ﷺ وغَيْره ﴿عَنْ مَواضِعه﴾ الَّتِي وضَعَهُ اللَّه عَلَيْها أيْ يُبَدِّلُونَهُ ﴿ونَسُوا﴾ تَرَكُوا ﴿حَظًّا﴾ نَصِيبًا ﴿مِمّا ذُكِّرُوا﴾ أُمِرُوا ﴿بِهِ﴾ فِي التَّوْراة مِن اتِّباع مُحَمَّد ﴿ولا تَزال﴾ خِطاب لِلنَّبِيِّ ﷺ ﴿تَطَّلِع﴾ تَظْهَر ﴿عَلى خائِنَة﴾ أيْ خِيانَة ﴿مِنهُمْ﴾ بِنَقْضِ العَهْد وغَيْره ﴿إلّا قَلِيلًا مِنهُمْ﴾ مِمَّنْ أسْلَمَ ﴿فاعْفُ عَنْهُمْ واصْفَحْ إنّ اللَّه يُحِبّ المُحْسِنِينَ﴾ وهَذا مَنسُوخ بِآيَةِ السَّيْف"],[14,14,"﴿ومِن الَّذِينَ قالُوا إنّا نَصارى﴾ مُتَعَلِّق بِقَوْلِهِ ﴿أخَذْنا مِيثاقهمْ﴾ كَما أخَذْنا عَلى بَنِي إسْرائِيل اليَهُود ﴿فَنَسُوا حَظًّا مِمّا ذُكِّرُوا بِهِ﴾ فِي الإنْجِيل مِن الإيمان وغَيْره ونَقَضُوا المِيثاق ﴿فَأَغْرَيْنا﴾ أوْقَعْنا ﴿بَيْنهمْ العَداوَة والبَغْضاء إلى يَوْم القِيامَة﴾ بِتَفَرُّقِهِمْ واخْتِلاف أهْوائِهِمْ فَكُلّ فِرْقَة تُكَفِّر الأُخْرى ﴿وسَوْفَ يُنَبِّئهُمْ اللَّه﴾ فِي الآخِرَة ﴿بِما كانُوا يَصْنَعُونَ﴾ فَيُجازِيهِمْ عَلَيْهِ"],[15,15,"﴿يا أهْل الكِتاب﴾ اليَهُود والنَّصارى ﴿قَدْ جاءَكُمْ رَسُولنا﴾ مُحَمَّد ﴿يُبَيِّن لَكُمْ كَثِيرًا مِمّا كُنْتُمْ تُخْفُونَ﴾ تَكْتُمُونَ ﴿مِن الكِتاب﴾ التَّوْراة والإنْجِيل كَآيَةِ الرَّجْم وصِفَته ﴿ويَعْفُوا عَنْ كَثِير﴾ مِن ذَلِكَ فَلا يُبَيِّنهُ إذا لَمْ يَكُنْ فِيهِ مَصْلَحَة إلّا افْتِضاحكُمْ ﴿قَدْ جاءَكُمْ مِن اللَّه نُور﴾ هُوَ النَّبِيّ ﷺ ﴿وكِتاب﴾ قُرْآن ﴿مُبِين﴾ بَيِّن ظاهِر"],[16,16,"﴿يَهْدِي بِهِ﴾ أيْ بِالكِتابِ ﴿اللَّه مَن اتَّبَعَ رِضْوانه﴾ بِأَنْ آمَنَ ﴿سُبُل السَّلام﴾ طُرُق السَّلامَة ﴿ويُخْرِجهُمْ مِن الظُّلُمات﴾ الكُفْر ﴿إلى النُّور﴾ الإيمان ﴿بِإذْنِهِ﴾ بِإرادَتِهِ ﴿ويَهْدِيهِمْ إلى صِراط مُسْتَقِيم﴾ دِين الإسْلام"],[17,17,"﴿لَقَدْ كَفَرَ الَّذِينَ قالُوا إنّ اللَّه هُوَ المَسِيح ابْن مَرْيَم﴾ حَيْثُ جَعَلُوهُ إلَهًا وهُمْ اليَعْقُوبِيَّة فِرْقَة مِن النَّصارى ﴿قُلْ فَمَن يَمْلِك﴾ أيْ يَدْفَع ﴿مِن﴾ عَذاب ﴿اللَّه شَيْئًا إنْ أرادَ أنْ يُهْلِك المَسِيح ابْن مَرْيَم وأُمّه ومَن فِي الأَرْض جَمِيعًا﴾ أيْ لا أحَد يَمْلِك ذَلِكَ ولَوْ كانَ المَسِيح إلَهًا لَقَدَرَ عَلَيْهِ ﴿ولِلَّهِ مُلْك السَّمَوات والأَرْض وما بَيْنهما يَخْلُق ما يَشاء واللَّه عَلى كُلّ شَيْء﴾ شاءَهُ"],[18,18,"﴿وقالَتْ اليَهُود والنَّصارى﴾ أيْ كُلّ مِنهُما ﴿نَحْنُ أبْناء اللَّه وأَحِبّاؤُهُ﴾ أيْ كَأَبْنائِهِ فِي القُرْب والمَنزِلَة وهُوَ كَأَبِينا فِي الرَّحْمَة والشَّفَقَة ﴿قُلْ﴾ لَهُمْ يا مُحَمَّد ﴿فَلِمَ يُعَذِّبكُمْ بِذُنُوبِكُمْ﴾ إنْ صَدَقْتُمْ فِي ذَلِكَ ولا يُعَذِّب الأَب ولَده ولا الحَبِيب حَبِيبه وقَدْ عَذَّبَكُمْ فَأَنْتُمْ كاذِبُونَ ﴿بَلْ أنْتُمْ بَشَر مِمَّنْ﴾ مِن جُمْلَة مَن ﴿خَلَقَ﴾ مِن البَشَر لَكُمْ ما لَهُمْ وعَلَيْكُمْ ما عَلَيْهِمْ ﴿يَغْفِر لِمَن يَشاء﴾ المَغْفِرَة لَهُ ﴿ويُعَذِّب مَن يَشاء﴾ تَعْذِيبه لا اعْتِراض عَلَيْهِ ﴿ولِلَّهِ مُلْك السَّماوات والأَرْض وما بَيْنهما وإلَيْهِ المَصِير﴾ المَرْجِع"],[19,19,"﴿يا أهْل الكِتاب قَدْ جاءَكُمْ رَسُولنا﴾ مُحَمَّد ﴿يُبَيِّن لَكُمْ﴾ شَرائِع الدِّين ﴿عَلى فَتْرَة﴾ انْقِطاع ﴿مِن الرُّسُل﴾ إذْ لَمْ يَكُنْ بَيْنه وبَيْن عِيسى رَسُول ومُدَّة ذَلِكَ خَمْسمِائَةٍ وتِسْع وسِتُّونَ سَنَة لـ ﴿أنْ﴾ لا ﴿تَقُولُوا﴾ إذا عُذِّبْتُمْ ﴿ما جاءَنا مِن﴾ زائِدَة ﴿بَشِير ولا نَذِير فَقَدْ جاءَكُمْ بَشِير ونَذِير﴾ فَلا عُذْر لَكُمْ إذًا ﴿واللَّه عَلى كُلّ شَيْء قَدِير﴾ ومِنهُ تَعْذِيبكُمْ إنْ لَمْ تَتَّبِعُوهُ"],[20,20,"﴿و﴾ اُذْكُرْ ﴿إذْ قالَ مُوسى لِقَوْمِهِ يا قَوْم اُذْكُرُوا نِعْمَة اللَّه عَلَيْكُمْ إذْ جَعَلَ فِيكُمْ﴾ أيْ مِنكُمْ ﴿أنْبِياء وجَعَلَكُمْ مُلُوكًا﴾ أصْحاب خَدَم وحَشَم ﴿وآتاكُمْ ما لَمْ يُؤْتِ أحَدًا مِن العالَمِينَ﴾ مِن المَنّ والسَّلْوى وفَلْق البَحْر وغَيْر ذَلِكَ"],[21,21,"﴿يا قَوْم اُدْخُلُوا الأَرْض المُقَدَّسَة﴾ المُطَهَّرَة ﴿الَّتِي كَتَبَ اللَّه لَكُمْ﴾ أمَرَكُمْ بِدُخُولِها وهِيَ الشّام ﴿ولا تَرْتَدُّوا عَلى أدْباركُمْ﴾ تَنْهَزِمُوا خَوْف العَدُوّ ﴿فَتَنْقَلِبُوا خاسِرِينَ﴾ فِي سَعْيكُمْ"],[22,22,"﴿قالُوا يا مُوسى إنّ فِيها قَوْمًا جَبّارِينَ﴾ مِن بَقايا عاد طُوالًا ذِي قُوَّة ﴿وإنّا لَنْ نَدْخُلها حَتّى يَخْرُجُوا مِنها فَإنْ يَخْرُجُوا مِنها فَإنّا داخِلُونَ﴾ لَها"],[23,23,"﴿قالَ﴾ لَهُمْ ﴿رَجُلانِ مِن الَّذِينَ يَخافُونَ﴾ مُخالَفَة أمْر اللَّه وهُما يُوشَع وكالِب مِن النُّقَباء الَّذِينَ بَعَثَهُمْ مُوسى فِي كَشْف أحْوال الجَبابِرَة ﴿أنْعَمَ اللَّه عَلَيْهِما﴾ بِالعِصْمَةِ فَكَتَما ما اطَّلَعا عَلَيْهِ مِن حالهمْ إلّا عَنْ مُوسى بِخِلافِ بَقِيَّة النُّقَباء فَأَفْشَوْهُ فَجَبُنُوا ﴿اُدْخُلُوا عَلَيْهِمْ الباب﴾ باب القَرْيَة ولا تَخْشَوْهُمْ فَإنَّهُمْ أجْساد بِلا قُلُوب ﴿فَإذا دَخَلْتُمُوهُ فَإنَّكُمْ غالِبُونَ﴾ قالا ذَلِكَ تَيَقُّنًا بِنَصْرِ اللَّه وإنْجاز وعْده"],[24,24,"﴿قالُوا يا مُوسى إنّا لَنْ نَدْخُلها أبَدًا ما دامُوا فِيها فاذْهَبْ أنْت ورَبّك فَقاتِلا﴾ هُمْ ﴿إنّا هاهُنا قاعِدُونَ﴾ عَنْ القِتال"],[25,25,"﴿قالَ﴾ مُوسى حِينَئِذٍ ﴿رَبّ إنِّي لا أمْلِك إلّا نَفْسِي وأَخِي﴾ ولا أمْلِك غَيْرهما فَأُجْبِرهُمْ عَلى الطّاعَة ﴿فافْرُقْ﴾ فافْصِلْ"],[26,26,"﴿قالَ﴾ تَعالى لَهُ ﴿فَإنَّها﴾ أيْ الأَرْض المُقَدَّسَة ﴿مُحَرَّمَة عَلَيْهِمْ﴾ أنْ يَدْخُلُوها ﴿أرْبَعِينَ سَنَة يَتِيهُونَ﴾ يَتَحَيَّرُونَ ﴿فِي الأَرْض﴾ وهِيَ تِسْعَة فَراسِخ قالَهُ ابْن عَبّاس ﴿فَلا تَأْسَ﴾ تَحْزَن ﴿عَلى القَوْم الفاسِقِينَ﴾ رُوِيَ أنَّهُمْ كانُوا يَسِيرُونَ اللَّيْل جادِّينَ فَإذا أصْبَحُوا إذا هُمْ فِي المَوْضِع الَّذِي ابْتَدَءُوا مِنهُ ويَسِيرُونَ النَّهار كَذَلِكَ حَتّى انْقَرَضُوا كُلّهمْ إلّا مَن لَمْ يَبْلُغ العِشْرِينَ قِيلَ: وكانُوا سِتّمِائَةِ ألْف وماتَ هارُونَ ومُوسى فِي التِّيه وكانَ رَحْمَة لَهُما وعَذابًا لِأُولَئِكَ وسَأَلَ مُوسى رَبّه عِنْد مَوْته أنْ يُدْنِيه مِن الأَرْض المُقَدَّسَة رَمْيَة بِحَجَرٍ فَأَدْناهُ كَما فِي الحَدِيث ونَبِّئْ يُوشَع بَعْد الأَرْبَعِينَ وأُمِرَ بِقِتالِ الجَبّارِينَ فَسارَ بِمَن بَقِيَ مَعَهُ وقاتَلَهُمْ وكانَ يَوْم الجُمُعَة ووَقَفَتْ لَهُ الشَّمْس ساعَة حَتّى فَرَغَ مِن قِتالهمْ ورَوى أحْمَد فِي مُسْنَده حَدِيث إنّ الشَّمْس لَمْ تُحْبَس عَلى بَشَر إلّا لِيُوشَع لَيالِي سارَ إلى بَيْت المَقْدِس"],[27,27,"﴿واتْلُ﴾ يا مُحَمَّد ﴿عَلَيْهِمْ﴾ عَلى قَوْمك ﴿نَبَأ﴾ خَبَر ﴿ابْنَيْ آدَم﴾ هابِيل وقابِيل ﴿بِالحَقِّ﴾ مُتَعَلِّق باُتْلُ ﴿إذْ قَرَّبا قُرْبانًا﴾ إلى اللَّه وهُوَ كَبْش لِهابِيلَ وزَرْع لِقابِيلَ ﴿فَتُقُبِّلَ مِن أحَدهما﴾ وهُوَ هابِيل بِأَنْ نَزَلَتْ نار مِن السَّماء فَأَكَلَتْ قُرْبانه ﴿ولَمْ يُتَقَبَّل مِن الآخَر﴾ وهُوَ قابِيل فَغَضِبَ وأَضْمَرَ الحَسَد فِي نَفْسه إلى أنْ حَجّ آدَم ﴿قالَ﴾ لَهُ ﴿لَأَقْتُلَنك﴾ قالَ: لِمَ ؟ قالَ لِتَقَبُّلِ قُرْبانك دُونِي"],[28,28,"﴿لَئِنْ﴾ لام قَسَم ﴿بَسَطْت﴾ مَدَدْت ﴿إلَيَّ يَدك لِتَقْتُلنِي ما أنا بِباسِطٍ يَدِي إلَيْك لِأَقْتُلك إنِّي أخاف اللَّه رَبّ العالَمِينَ﴾ فِي قَتْلك"],[29,29,"﴿إنِّي أُرِيد أنْ تَبُوء﴾ تَرْجِع ﴿بِإثْمِي﴾ بِإثْمِ قَتْلِي ﴿وإثْمك﴾ الَّذِي ارْتَكَبْته مِن قَبْل ﴿فَتَكُون مِن أصْحاب النّار﴾ ولا أُرِيد أنْ أبُوء بِإثْمِك إذا قَتَلْتُك فَأَكُون مِنهُمْ قالَ تَعالى: ﴿وذَلِكَ جَزاء الظّالِمِينَ﴾"],[30,30,"﴿فَطَوَّعَتْ﴾ زَيَّنَتْ ﴿لَهُ نَفْسه قَتْل أخِيهِ فَقَتَلَهُ فَأَصْبَحَ﴾ فَصارَ ﴿مِن الخاسِرِينَ﴾ بِقَتْلِهِ ولَمْ يَدْرِ ما يَصْنَع بِهِ لِأَنَّهُ أوَّل مَيِّت عَلى وجْه الأَرْض مِن بَنِي آدَم فَحَمَلَهُ عَلى ظَهْره"],[31,31,"﴿فَبَعَثَ اللَّه غُرابًا يَبْحَث فِي الأَرْض﴾ يَنْبُش التُّراب بِمِنقارِهِ وبِرِجْلَيْهِ ويُثِيرهُ عَلى غُراب مَيِّت حَتّى واراهُ ﴿لِيُرِيَهُ كَيْفَ يُوارِي﴾ يَسْتُر ﴿سَوْأَة﴾ جِيفَة ﴿أخِيهِ قالَ يا ويْلَتى أعَجَزْت﴾ عَنْ ﴿أنْ أكُون مِثْل هَذا الغُراب فَأُوارِي سَوْأَة أخِي فَأَصْبَحَ مِن النّادِمِينَ﴾ عَلى حَمْله وحَفَرَ لَهُ وواراهُ"],[32,32,"﴿مِن أجْل ذَلِكَ﴾ الَّذِي فَعَلَهُ قابِيل ﴿كَتَبْنا عَلى بَنِي إسْرائِيل أنَّهُ﴾ أيْ الشَّأْن ﴿مَن قَتَلَ نَفْسًا بِغَيْرِ نَفْس﴾ قَتَلَها ﴿أوْ﴾ بِغَيْرِ ﴿فَساد﴾ أتاهُ ﴿فِي الأَرْض﴾ مِن كُفْر أوْ زِنًا أوْ قَطْع طَرِيق أوْ نَحْوه ﴿فَكَأَنَّما قَتَلَ النّاس جَمِيعًا ومَن أحْياها﴾ بِأَنْ امْتَنَعَ عَنْ قَتْلها ﴿فَكَأَنَّما أحْيا النّاس جَمِيعًا﴾ قالَ ابْن عَبّاس: مِن حَيْثُ انْتِهاك حُرْمَتها وصَوْنها ﴿ولَقَدْ جاءَتْهُمْ﴾ أيْ بَنِي إسْرائِيل ﴿رُسُلنا بِالبَيِّناتِ﴾ المُعْجِزات ﴿ثُمَّ إنّ كَثِيرًا مِنهُمْ بَعْد ذَلِكَ فِي الأَرْض لَمُسْرِفُونَ﴾ مُجاوِزُونَ الحَدّ بِالكُفْرِ والقَتْل وغَيْر ذَلِكَ"],[33,33,"ونَزَلَ فِي العُرَنِيِّينَ لَمّا قَدِمُوا المَدِينَة وهُمْ مَرْضى فَأَذِنَ لَهُمْ النَّبِيّ ﷺ أنْ يَخْرُجُوا إلى الإبِل ويَشْرَبُوا مِن أبْوالها وأَلْبانها فَلَمّا صَحُّوا قَتَلُوا راعِي النَّبِيّ ﷺ واسْتاقُوا الإبِل ﴿إنّما جَزاء الَّذِينَ يُحارِبُونَ اللَّه ورَسُوله﴾ بِمُحارَبَةِ المُسْلِمِينَ ﴿ويَسْعَوْنَ فِي الأَرْض فَسادًا﴾ بِقَطْعِ الطَّرِيق ﴿أنْ يُقَتَّلُوا أوْ يُصَلَّبُوا أوْ تُقَطَّع أيْدِيهمْ وأَرْجُلهمْ مِن خِلاف﴾ أيْ أيْدِيهمْ اليُمْنى وأَرْجُلهمْ اليُسْرى ﴿أوْ يُنْفَوْا مِن الأَرْض﴾ أوْ لِتَرْتِيبِ الأَحْوال فالقَتْل لِمَن قَتَلَ فَقَطْ والصَّلْب لِمَن قَتَلَ وأَخَذَ المال والقَطْع لِمَن أخَذَ المال ولَمْ يَقْتُل والنَّفْي لِمَن أخاف فَقَطْ قالَهُ ابْن عَبّاس وعَلَيْهِ الشّافِعِيّ وأَصَحّ قَوْلَيْهِ أنَّ الصَّلْب ثَلاثًا بَعْد القَتْل وقِيلَ قَبْله قَلِيلًا ويُلْحَق بِالنَّفْيِ ما أشْبَهَهُ فِي التَّنْكِيل مِن الحَبْس وغَيْره ﴿ذَلِكَ﴾ الجَزاء المَذْكُور ﴿لَهُمْ خِزْي﴾ ذُلّ ﴿فِي الدُّنْيا ولَهُمْ فِي الآخِرَة عَذاب عَظِيم﴾ هُوَ عَذاب النّار"],[34,34,"﴿إلّا الَّذِينَ تابُوا﴾ مِن المُحارِبِينَ والقُطّاع ﴿مِن قَبْل أنْ تَقْدِرُوا عَلَيْهِمْ فاعْلَمُوا أنَّ اللَّه غَفُور﴾ لَهُمْ ما أتَوْهُ ﴿رَحِيم﴾ بِهِمْ عَبَّرَ بِذَلِك دُون فَلا تَحُدُّوهُمْ لِيُفِيدَ أنَّهُ لا يَسْقُط عَنْهُ بِتَوْبَتِهِ إلّا حُدُود اللَّه دُون حُقُوق الآدَمِيِّينَ كَذا ظَهَرَ لِي ولَمْ أرَ مَن تَعَرَّضَ لَهُ واللَّه أعْلَم فَإذا قَتَلَ وأَخَذَ المال يُقْتَل ويُقْطَع ولا يُصْلَب وهُوَ أصَحّ قَوْلَيْ الشّافِعِيّ ولا تُفِيد تَوْبَته بَعْد القُدْرَة عَلَيْهِ شَيْئًا وهُوَ أصَحّ قَوْلَيْهِ أيْضًا"],[35,35,"﴿يا أيّها الَّذِينَ آمَنُوا اتَّقُوا اللَّه﴾ خافُوا عِقابه بِأَنْ تُطِيعُوهُ ﴿وابْتَغُوا﴾ اُطْلُبُوا ﴿إلَيْهِ الوَسِيلَة﴾ ما يُقَرِّبكُمْ إلَيْهِ مِن طاعَته ﴿وجاهِدُوا فِي سَبِيله﴾ لِإعْلاءِ دِينه ﴿لَعَلَّكُمْ تُفْلِحُونَ﴾ تَفُوزُونَ"],[36,36,"﴿إنّ الَّذِينَ كَفَرُوا لَوْ﴾ ثَبَتَ ﴿أنَّ لَهُمْ ما فِي الأَرْض جَمِيعًا ومِثْله مَعَهُ لِيَفْتَدُوا بِهِ مِن عَذاب يَوْم القِيامَة ما تُقُبِّلَ مِنهُمْ ولَهُمْ عَذاب ألِيم﴾"],[37,37,"﴿يُرِيدُونَ﴾ يَتَمَنَّوْنَ ﴿أنْ يَخْرُجُوا مِن النّار وما هُمْ بِخارِجِينَ مِنها ولَهُمْ عَذاب مُقِيم﴾ دائِم"],[38,38,"﴿والسّارِق والسّارِقَة﴾ ألْ فِيهِما مَوْصُولَة مُبْتَدَأ ولِشَبَهِهِ بِالشَّرْطِ دَخَلَتْ الفاء فِي خَبَره وهُوَ ﴿فاقْطَعُوا أيْدِيهما﴾ أيْ يَمِين كُلّ مِنهُما مِن الكُوع وبَيَّنَتْ السُّنَّة أنَّ الَّذِي يُقْطَع فِيهِ رُبُع دِينار فَصاعِدًا وأَنَّهُ إذا عادَ قُطِعَتْ رِجْله اليُسْرى مِن مَفْصِل القَدَم ثُمَّ اليَد اليُسْرى ثُمَّ الرِّجْل اليُمْنى وبَعْد ذَلِكَ يُعَزَّر ﴿جَزاء﴾ نُصِبَ عَلى المَصْدَر ﴿بِما كَسَبا نَكالًا﴾ عُقُوبَة لَهُما ﴿مِن اللَّه واللَّه عَزِيز﴾ غالِب عَلى أمْره ﴿حَكِيم﴾ فِي خَلْقه."],[39,39,"﴿فَمَن تابَ مِن بَعْد ظُلْمه﴾ رَجَعَ عَنْ السَّرِقَة ﴿وأَصْلَحَ﴾ عَمَله ﴿فَإنَّ اللَّه يَتُوب عَلَيْهِ إنّ اللَّه غَفُور رَحِيم﴾ فِي التَّعْبِير بِهَذا ما تَقَدَّمَ فَلا يَسْقُط بِتَوْبَتِهِ حَقّ الآدَمِيّ مِن القَطْع ورَدّ المال نَعَمْ بَيَّنَتْ السُّنَّة أنَّهُ إنْ عَفا عَنْهُ قَبْل الرَّفْع إلى الإمام سَقَطَ القَطْع وعَلَيْهِ الشّافِعِيّ"],[40,40,"﴿ألَمْ تَعْلَم﴾ الِاسْتِفْهام فِيهِ لِلتَّقْرِيرِ ﴿أنَّ اللَّه لَهُ مُلْك السَّمَوات والأَرْض يُعَذِّب مَن يَشاء﴾ تَعْذِيبه ﴿ويَغْفِر لِمَن يَشاء﴾ المَغْفِرَة لَهُ ﴿واللَّه عَلى كُلّ شَيْء قَدِير﴾ ومِنهُ التَّعْذِيب والمَغْفِرَة"],[41,41,"﴿يا أيّها الرَّسُول لا يَحْزُنك﴾ صُنْع ﴿الَّذِينَ يُسارِعُونَ فِي الكُفْر﴾ يَقَعُونَ فِيهِ بِسُرْعَةٍ أيْ يُظْهِرُونَهُ إذا وجَدُوا فُرْصَة ﴿مِن﴾ لِلْبَيانِ ﴿الَّذِينَ قالُوا آمَنّا بِأَفْواهِهِمْ﴾ بِأَلْسِنَتِهِمْ مُتَعَلِّق بِقالُوا ﴿ولَمْ تُؤْمِن قُلُوبهمْ﴾ وهُمْ المُنافِقُونَ ﴿ومِن الَّذِينَ هادُوا﴾ قَوْم ﴿سَمّاعُونَ لِلْكَذِبِ﴾ الَّذِي افْتَرَتْهُ أحْبارهمْ سَماع قَبُول ﴿سَمّاعُونَ﴾ مِنك ﴿لِقَوْمٍ﴾ لِأَجْلِ قَوْم ﴿آخَرِينَ﴾ مِن اليَهُود ﴿لَمْ يَأْتُوك﴾ وهُمْ أهْل خَيْبَر زَنى فِيهِمْ مُحْصَنانِ فَكَرِهُوا رَجْمهما فَبَعَثُوا قُرَيْظَة لِيَسْأَلُوا النَّبِيّ ﷺ عَنْ حُكْمهما ﴿يُحَرِّفُونَ الكَلِم﴾ الَّذِي فِي التَّوْراة كَآيَةِ الرَّجْم ﴿مِن بَعْد مَواضِعه﴾ الَّتِي وضَعَهُ اللَّه عَلَيْها أيْ يُبَدِّلُونَهُ ﴿يَقُولُونَ﴾ لِمَن أرْسَلُوهُمْ ﴿إنْ أُوتِيتُمْ هَذا﴾ الحُكْم المُحَرَّف أيْ الجَلْد الَّذِي أفْتاكُمْ بِهِ مُحَمَّد ﴿فَخُذُوهُ﴾ فاقْبَلُوهُ ﴿وإنْ لَمْ تُؤْتَوْهُ﴾ بَلْ أفْتاكُمْ بِخِلافِهِ ﴿فاحْذَرُوا﴾ أنْ تَقْبَلُوهُ ﴿ومَن يُرِدْ اللَّه فِتْنَته﴾ إضْلاله ﴿فَلَنْ تَمْلِك لَهُ مِن اللَّه شَيْئًا﴾ فِي دَفْعها ﴿أُولَئِكَ الَّذِينَ لَمْ يُرِدْ اللَّه أنْ يُطَهِّر قُلُوبهمْ﴾ مِن الكُفْر ولَوْ أرادَهُ لَكانَ ﴿لَهُمْ فِي الدُّنْيا خِزْي﴾ ذُلّ بِالفَضِيحَةِ والجِزْيَة"],[42,42,"﴿سَمّاعُونَ لِلْكَذِبِ أكّالُونَ لِلسُّحْتِ﴾ بِضَمِّ الحاء وسُكُونها أيْ الحَرام كالرِّشا ﴿فَإنْ جاءُوك﴾ لِتَحْكُم بَيْنهمْ ﴿فاحْكُمْ بَيْنهمْ أوْ أعْرِض عَنْهُمْ﴾ هَذا التَّخْيِير مَنسُوخ بِقَوْلِهِ تَعالى ﴿وأَنْ اُحْكُمْ بَيْنهمْ﴾ الآيَة فَيَجِب الحُكْم بَيْنهمْ إذا تَرافَعُوا إلَيْنا وهُوَ أصَحّ قَوْلَيْ الشّافِعِيّ فَلَوْ تَرافَعُوا إلَيْنا مَعَ مُسْلِم وجَبَ إجْماعًا ﴿وإنْ تُعْرِض عَنْهُمْ فَلَنْ يَضُرُّوك شَيْئًا وإنْ حَكَمْت﴾ بَيْنهمْ ﴿فاحْكُمْ بَيْنهمْ بِالقِسْطِ﴾ بِالعَدْلِ ﴿إنّ اللَّه يُحِبّ المُقْسِطِينَ﴾ العادِلِينَ فِي الحُكْم أيْ يُثِيبهُمْ"],[43,43,"﴿وكَيْفَ يُحَكِّمُونَك وعِنْدهمْ التَّوْراة فِيها حُكْم اللَّه﴾ بِالرَّجْمِ وهُوَ اسْتِفْهام تَعْجِيب أيْ لَمْ يَقْصِدُوا بِذَلِك مَعْرِفَة الحَقّ بَلْ ما هُوَ أهْوَن عَلَيْهِمْ ﴿ثُمَّ يَتَوَلَّوْنَ﴾ يُعْرِضُونَ عَنْ حُكْمك بِالرَّجْمِ المُوافِق لِكِتابِهِمْ ﴿مِن بَعْد ذَلِكَ﴾ التَّحْكِيم"],[44,44,"﴿إنّا أنْزَلْنا التَّوْراة فِيها هُدًى﴾ مِن الضَّلالَة ﴿ونُور﴾ بَيان لِلْأَحْكامِ ﴿يَحْكُم بِها النَّبِيُّونَ﴾ مِن بَنِي إسْرائِيل ﴿الَّذِينَ أسْلَمُوا﴾ انْقادُوا لِلَّهِ ﴿لِلَّذِينَ هادُوا والرَّبّانِيُّون﴾ العُلَماء مِنهُ ﴿والأَحْبار﴾ الفُقَهاء ﴿بِما﴾ أيْ بِسَبَبِ الَّذِي ﴿اُسْتُحْفِظُوا﴾ اُسْتُوْدِعُوهُ أيْ اسْتَحْفَظَهُمْ اللَّه إيّاهُ ﴿مِن كِتاب اللَّه﴾ أنْ يُبَدِّلُوهُ ﴿وكانُوا عَلَيْهِ شُهَداء﴾ أنَّهُ حَقّ ﴿فَلا تَخْشَوْا النّاس﴾ أيّها اليَهُود فِي إظْهار ما عِنْدكُمْ مِن نَعْت مُحَمَّد ﷺ والرَّجْم وغَيْرها ﴿واخْشَوْنِي﴾ فِي كِتْمانه ﴿ولا تَشْتَرُوا﴾ تَسْتَبْدِلُوا ﴿بِآياتِي ثَمَنًا قَلِيلًا﴾ مِن الدُّنْيا تَأْخُذُونَهُ عَلى كِتْمانها ﴿ومَن لَمْ يَحْكُم بِما أنْزَلَ اللَّه فَأُولَئِكَ هُمْ الكافِرُونَ﴾ بِهِ"],[45,45,"﴿وكَتَبْنا﴾ فَرَضْنا ﴿عَلَيْهِمْ فِيها﴾ أيْ التَّوْراة ﴿أنَّ النَّفْس﴾ تُقْتَل ﴿بِالنَّفْسِ﴾ إذا قَتَلَتْها ﴿والعَيْن بِالعَيْنِ﴾ تُفْقَأ ﴿والأَنْف بِالأَنْفِ﴾ يُجْدَع ﴿والأُذُن بِالأُذُنِ﴾ تُقْطَع ﴿والسِّنّ بِالسِّنِّ﴾ تُقْلَع وفِي قِراءَة بِالرَّفْعِ فِي الأَرْبَعَة ﴿والجُرُوح﴾ بِالوَجْهَيْنِ ﴿قِصاص﴾ أيْ يُقْتَصّ فِيها إذا أمْكَنَ كاليَدِ والرِّجْل ونَحْو ذَلِكَ وما لا يُمْكِن فِيهِ الحُكُومَة وهَذا الحُكْم وإنْ كَتَبَ عَلَيْهِمْ فَهُوَ مُقَرَّر فِي شَرْعنا ﴿فَمَن تَصَدَّقَ بِهِ﴾ أيْ بِالقِصاصِ بِأَنْ مَكَّنَ مِن نَفْسه ﴿فَهُوَ كَفّارَة لَهُ﴾ لِما أتاهُ ﴿ومَن لَمْ يَحْكُم بِما أنْزَلَ اللَّه﴾ فِي القِصاص وغَيْره"],[46,46,"﴿وقَفَّيْنا﴾ أتْبَعنا ﴿عَلى آثارهمْ﴾ أيْ النَّبِيِّينَ ﴿بِعِيسى ابْن مَرْيَم مُصَدِّقًا لِما بَيْن يَدَيْهِ﴾ قَبْله ﴿مِن التَّوْراة وآتَيْناهُ الإنْجِيل فِيهِ هُدًى﴾ مِن الضَّلالَة ﴿ونُور﴾ بَيان لِلْأَحْكامِ ﴿ومُصَدِّقًا﴾ حال ﴿لِما بَيْن يَدَيْهِ مِن التَّوْراة﴾ لِما فِيها مِن الأَحْكام"],[47,47,"﴿و﴾ قُلْنا ﴿لِيَحْكُم أهْل الإنْجِيل بِما أنْزَلَ اللَّه فِيهِ﴾ مِن الأَحْكام وفِي قِراءَة بِنَصْبِ يَحْكُم وكَسْر لامه عَطْفًا عَلى مَعْمُول آتَيْناهُ"],[48,48,"﴿وأَنْزَلْنا إلَيْك﴾ يا مُحَمَّد ﴿الكِتاب﴾ القُرْآن ﴿بِالحَقِّ﴾ مُتَعَلِّق بأَنْزَلْنا ﴿مُصَدِّقًا لِما بَيْن يَدَيْهِ﴾ قَبْله ﴿مِن الكِتاب ومُهَيْمِنًا﴾ شاهِدًا ﴿عَلَيْهِ﴾ والكِتاب بِمَعْنى الكُتُب ﴿فاحْكُمْ بَيْنهمْ﴾ بَيْن أهْل الكِتاب إذا تَرافَعُوا إلَيْك ﴿بِما أنْزَلَ اللَّه﴾ إلَيْك ﴿ولا تَتَّبِع أهْواءَهُمْ﴾ عادِلًا ﴿عَمّا جاءَك مِن الحَقّ لِكُلٍّ جَعَلْنا مِنكُمْ﴾ أيّها الأُمَم ﴿شِرْعَة﴾ شَرِيعَة ﴿ومِنهاجًا﴾ طَرِيقًا واضِحًا فِي الدِّين يَمْشُونَ عَلَيْهِ ﴿ولَوْ شاءَ اللَّه لَجَعَلَكُمْ أُمَّة واحِدَة﴾ عَلى شَرِيعَة واحِدَة ﴿ولَكِنْ﴾ فَرَّقَكُمْ فِرَقًا ﴿لِيَبْلُوكُمْ﴾ لِيَخْتَبِركُمْ ﴿فِي ما آتاكُمْ﴾ مِن الشَّرائِع المُخْتَلِفَة لِيَنْظُر المُطِيع مِنكُمْ والعاصِي. ﴿فاسْتَبِقُوا الخَيْرات﴾ سارِعُوا إلَيْها ﴿إلى اللَّه مَرْجِعكُمْ جَمِيعًا﴾ بِالبَعْثِ ﴿فَيُنَبِّئكُمْ بِما كُنْتُمْ فِيهِ تَخْتَلِفُونَ﴾ مِن أمْر الدِّين ويَجْزِي كُلًّا مِنكُمْ بِعَمَلِهِ"],[49,49,"لـ ﴿أنْ﴾ لا ﴿يَفْتِنُوك﴾ يُضِلُّوك ﴿عَنْ بَعْض ما أنْزَلَ اللَّه إلَيْك فَإنْ تَوَلَّوْا﴾ عَنْ الحُكْم المُنَزَّل وأَرادُوا غَيْره ﴿فاعْلَمْ أنَّما يُرِيد اللَّه أنْ يُصِيبهُمْ﴾ بِالعُقُوبَةِ فِي الدُّنْيا ﴿بِبَعْضِ ذُنُوبهمْ﴾ الَّتِي أتَوْها ومِنها التَّوَلِّي ويُجازِيهِمْ عَلى جَمِيعها فِي الأُخْرى"],[50,50,"﴿أفَحُكْم الجاهِلِيَّة يَبْغُونَ﴾ بِالياءِ والتّاء يَطْلُبُونَ مِن المُداهَنَة والمَيْل إذا تَوَلَّوْا ؟ اسْتِفْهام إنْكارِيّ ﴿ومَن﴾ أيْ لا أحَد ﴿أحْسَن مِن اللَّه حُكْمًا لِقَوْمٍ﴾ عِنْد قَوْم ﴿يُوقِنُونَ﴾ بِهِ خُصُّوا بِالذِّكْرِ لِأَنَّهُمْ الَّذِينَ يَتَدَبَّرُونَ"],[51,51,"﴿يا أيّها الَّذِينَ آمَنُوا لا تَتَّخِذُوا اليَهُود والنَّصارى أوْلِياء﴾ تُوالُونَهُمْ وتُوادُّونَهُمْ ﴿بَعْضهمْ أوْلِياء بَعْض﴾ لِاتِّحادِهِمْ فِي الكُفْر ﴿ومَن يَتَوَلَّهُمْ مِنكُمْ فَإنَّهُ مِنهُمْ﴾ مِن جُمْلَتهمْ ﴿إنّ اللَّه لا يَهْدِي القَوْم الظّالِمِينَ﴾ بِمُوالاتِهِمْ الكُفّار"],[52,52,"﴿فَتَرى الَّذِينَ فِي قُلُوبهمْ مَرَض﴾ ضَعْف اعْتِقاد كَعَبْدِ اللَّه بْن أُبَيٍّ المُنافِق ﴿يُسارِعُونَ فِيهِمْ﴾ فِي مُوالاتهمْ ﴿يَقُولُونَ﴾ مُعْتَذِرِينَ عَنْها ﴿نَخْشى أنْ تُصِيبنا دائِرَة﴾ يَدُور بِها الدَّهْر عَلَيْنا مِن جَدَب أوْ غَلَبَة ولا يَتِمّ أمْر مُحَمَّد فَلا يَمِيرُونا ﴿فَعَسى اللَّه أنْ يَأْتِي بِالفَتْحِ﴾ بِالنَّصْرِ لِنَبِيِّهِ بِإظْهارِ دِينه ﴿أوْ أمْر مِن عِنْده﴾ يَهْتِك سِتْر المُنافِقِينَ وافْتِضاحهمْ ﴿فَيُصْبِحُوا عَلى ما أسَرُّوا فِي أنْفُسهمْ﴾ مِن الشَّكّ ومُوالاة الكُفّار"],[53,53,"﴿ويَقُول﴾ بِالرَّفْعِ اسْتِئْنافًا بِواوٍ ودُونها وبِالنَّصْبِ عَطْفًا عَلى يَأْتِي ﴿الَّذِينَ آمَنُوا﴾ لِبَعْضِهِمْ إذا هَتَكَ سِتْرهمْ تَعَجُّبًا ﴿أهَؤُلاءِ الَّذِينَ أقْسَمُوا بِاللَّهِ جَهْد أيْمانهمْ﴾ غايَة اجْتِهادهمْ فِيها ﴿إنّهُمْ لَمَعَكُمْ﴾ فِي الدِّين ﴿حَبِطَتْ﴾ بَطَلَتْ ﴿أعْمالهمْ﴾ الصّالِحَة ﴿فَأَصْبَحُوا﴾ صارُوا ﴿خاسِرِينَ﴾ الدُّنْيا بِالفَضِيحَةِ والآخِرَة بِالعِقابِ"],[54,54,"﴿يا أيّها الَّذِينَ آمَنُوا مَن يَرْتَدّ﴾ بِالفَكِّ والإدْغام يَرْجِع ﴿مِنكُمْ عَنْ دِينه﴾ إلى الكُفْر إخْبار بِما عَلِمَ اللَّه وُقُوعه وقَدْ ارْتَدَّ جَماعَة بَعْد مَوْت النَّبِيّ ﷺ ﴿فَسَوْفَ يَأْتِي اللَّه﴾ بَدَلهمْ ﴿بِقَوْمٍ يُحِبّهُمْ ويُحِبُّونَهُ﴾ قالَ ﷺ: \"هُمْ قَوْم هَذا وأَشارَ إلى أبِي مُوسى الأَشْعَرِيّ\" رَواهُ الحاكِم فِي صَحِيحه ﴿أذِلَّة عَلى المُؤْمِنِينَ﴾ عاطِفِينَ ﴿أعِزَّة عَلى الكافِرِينَ﴾ أشِدّاء ﴿يُجاهِدُونَ فِي سَبِيل اللَّه ولا يَخافُونَ لَوْمَة لائِم﴾ فِيهِ كَما يَخاف المُنافِقُونَ لَوْم الكُفّار ﴿ذَلِكَ فَضْل اللَّه يُؤْتِيه مَن يَشاء واللَّه واسِع﴾ كَثِير الفَضْل ﴿عَلِيم﴾ بِمَن هُوَ أهْله ونَزَلَ لَمّا قالَ ابْن سَلام يا رَسُول اللَّه إنّ قَوْمنا هَجَرُونا"],[55,55,"﴿إنّما ولِيّكُمْ اللَّه ورَسُوله والَّذِينَ آمَنُوا الَّذِينَ يُقِيمُونَ الصَّلاة ويُؤْتُونَ الزَّكاة وهُمْ راكِعُونَ﴾ خاشِعُونَ أوْ يُصَلُّونَ صَلاة التَّطَوُّع"],[56,56,"﴿ومَن يَتَوَلَّ اللَّه ورَسُوله والَّذِينَ آمَنُوا﴾ فَيُعِينهُمْ ويَنْصُرهُمْ ﴿فَإنَّ حِزْب اللَّه هُمْ الغالِبُونَ﴾ لِنَصْرِهِ إيّاهُمْ أوْقَعه مَوْقِع فَإنَّهُمْ بَيانًا لِأَنَّهُمْ مِن حِزْبه أيْ أتْباعه"],[57,57,"﴿يا أيّها الَّذِينَ آمَنُوا لا تَتَّخِذُوا الَّذِينَ اتَّخَذُوا دِينكُمْ هُزُوًا﴾ مَهْزُوءًا بِهِ ﴿ولَعِبًا مِن﴾ لِلْبَيانِ ﴿الَّذِينَ أُوتُوا الكِتاب مِن قَبْلكُمْ والكُفّار﴾ المُشْرِكِينَ بِالجَرِّ والنَّصْب ﴿أوْلِياء واتَّقُوا اللَّه﴾ بِتَرْكِ مُوالاتهمْ ﴿إنْ كُنْتُمْ مُؤْمِنِينَ﴾ صادِقِينَ فِي إيمانكُمْ"],[58,58,"﴿و﴾ الَّذِينَ ﴿إذا نادَيْتُمْ﴾ دَعَوْتُمْ ﴿إلى الصَّلاة﴾ بِالأَذانِ ﴿اتَّخَذُوها﴾ أيْ الصَّلاة ﴿هُزُوًا ولَعِبًا﴾ بِأَنْ يَسْتَهْزِئُوا بِها ويَتَضاحَكُوا ﴿ذَلِكَ﴾ الِاتِّخاذ ﴿بِأَنَّهُمْ﴾ أيْ بِسَبَبِ أنَّهُمْ ﴿قَوْم لا يَعْقِلُونَ﴾"],[59,59,"ونَزَلَ لَمّا قالَ اليَهُود لِلنَّبِيِّ ﷺ: بِمَن تُؤْمِن مِن الرُّسُل فَقالَ: ﴿بِاللَّهِ وما أُنْزِلَ إلَيْنا﴾ الآيَة فَلَمّا ذَكَرَ عِيسى قالُوا: لا نَعْلَم دِينًا شَرًّا مِن دِينكُمْ ﴿قُلْ يا أهْل الكِتاب هَلْ تَنْقِمُونَ﴾ تُنْكِرُونَ ﴿مِنّا إلّا أنْ آمَنّا بِاللَّهِ وما أُنْزِلَ إلَيْنا وما أُنْزِلَ مِن قَبْل﴾ إلى الأَنْبِياء ﴿وأَنَّ أكْثَركُمْ فاسِقُونَ﴾ عُطِفَ عَلى أنْ آمَنّا - المَعْنى ما تُنْكِرُونَ إلّا إيماننا ومُخالَفَتكُمْ فِي عَدَم قَبُوله المُعَبَّر عَنْهُ بِالفِسْقِ اللّازِم عَنْهُ ولَيْسَ هَذا مِمّا يُنْكَر"],[60,60,"﴿قُلْ هَلْ أُنَبِّئكُمْ﴾ أُخْبِركُمْ ﴿بِشَرٍّ مِن﴾ أهْل ﴿ذَلِكَ﴾ الَّذِي تَنْقِمُونَهُ ﴿مَثُوبَة﴾ ثَوابًا بِمَعْنى جَزاء ﴿عِنْد اللَّه﴾ هُوَ ﴿مَن لَعَنَهُ اللَّه﴾ أبْعَده عَنْ رَحْمَته ﴿وغَضِبَ عَلَيْهِ وجَعَلَ مِنهُمْ القِرَدَة والخَنازِير﴾ بِالمَسْخِ ﴿و﴾ مَن ﴿عَبَدَ الطّاغُوت﴾ الشَّيْطان بِطاعَتِهِ ورُوعِيَ فِي مِنهُمْ مَعْنى مِن وفِيما قَبْله لَفْظها وهُمْ اليَهُود وفِي قِراءَة بِضَمِّ باء عَبَدَ وإضافَته إلى ما بَعْد اسْم جَمْع لعَبَدَ ونَصْبه بِالعَطْفِ عَلى القِرَدَة ﴿أُولَئِكَ شَرّ مَكانًا﴾ تَمْيِيز لِأَنَّ مَأْواهُمْ النّار ﴿وأَضَلّ عَنْ سَواء السَّبِيل﴾ طَرِيق الحَقّ وأَصْل السَّواء الوَسَط وذَكَرَ شَرّ وأَضَلّ فِي مُقابَلَة قَوْلهمْ لا نَعْلَم دِينًا شَرًّا مِن دِينكُمْ"],[61,61,"﴿وإذا جاءُوكُمْ﴾ أيْ مُنافِقُو اليَهُود ﴿قالُوا آمَنّا وقَدْ دَخَلُوا﴾ إلَيْكُمْ مُتَلَبِّسِينَ ﴿بِالكُفْرِ وهُمْ قَدْ خَرَجُوا بِهِ﴾ مِن عِنْدكُمْ مُتَلَبِّسِينَ ولَمْ يُؤْمِنُوا ﴿واللَّه أعْلَم بِما كانُوا يَكْتُمُونَ﴾ واللَّه أعْلَم بِما كانُوا يَكْتُمُونَهُ مِن النِّفاق"],[62,62,"﴿وتَرى كَثِيرًا مِنهُمْ﴾ أيْ اليَهُود ﴿يُسارِعُونَ﴾ يَقَعُونَ سَرِيعًا ﴿فِي الإثْم﴾ الكَذِب ﴿والعُدْوان﴾ الظُّلْم ﴿وأَكْلهمْ السُّحْت﴾ الحَرام كالرِّشا ﴿لَبِئْسَ ما كانُوا يَعْمَلُونَ﴾ لَبِئْسَ ما كانُوا يَعْمَلُونَهُ عَمَلهمْ هَذا"],[63,63,"﴿لَوْلا﴾ هَلّا ﴿يَنْهاهُمْ الرَّبّانِيُّونَ والأَحْبار﴾ مِنهُمْ ﴿عَنْ قَوْلهمْ الإثْم﴾ الكَذِب ﴿وأَكْلهمْ السُّحْت لَبِئْسَ ما كانُوا يَصْنَعُونَ﴾ وأَكْلهمْ السُّحْت لَبِئْسَ ما كانُوا يَصْنَعُونَهُ تَرْك نَهْيهمْ"],[64,64,"﴿وقالَتْ اليَهُود﴾ لَمّا ضُيِّقَ عَلَيْهِمْ بِتَكْذِيبِهِمْ النَّبِيّ ﷺ بَعْد أنْ كانُوا أكْثَر النّاس مالًا ﴿يَد اللَّه مَغْلُولَة﴾ مَقْبُوضَة عَنْ إدْرار الرِّزْق عَلَيْنا كَنَّوْا بِهِ عَنْ البُخْل - تَعالى اللَّه عَنْ ذَلِكَ - ﴿غُلَّتْ﴾ أمْسَكَتْ ﴿أيْدِيهمْ﴾ عَنْ فِعْل الخَيْرات دُعاء عَلَيْهِمْ ﴿ولُعِنُوا بِما قالُوا بَلْ يَداهُ مَبْسُوطَتانِ﴾ مُبالَغَة فِي الوَصْف بِالجُودِ وثَنْي اليَد لِإفادَةِ الكَثْرَة إذْ غايَة ما يَبْذُلهُ السَّخِيّ مِن ماله أنْ يُعْطِي بِيَدَيْهِ ﴿يُنْفِق كَيْفَ يَشاء﴾ مِن تَوْسِيع وتَضْيِيق لا اعْتِراض عَلَيْهِ ﴿ولَيَزِيدَن كَثِيرًا مِنهُمْ ما أُنْزِلَ إلَيْك مِن رَبّك﴾ مِن القُرْآن ﴿طُغْيانًا وكُفْرًا﴾ لِكُفْرِهِمْ بِهِ ﴿وأَلْقَيْنا بَيْنهمْ العَداوَة والبَغْضاء إلى يَوْم القِيامَة﴾ فَكُلّ فِرْقَة مِنهُمْ تُخالِف الأُخْرى ﴿كُلَّما أوْقَدُوا نارًا لِلْحَرْبِ﴾ أيْ لِحَرْبِ النَّبِيّ ﷺ ﴿أطْفَأَها اللَّه﴾ أيْ كُلَّما أرادُوهُ رَدَّهُمْ ﴿ويَسْعَوْنَ فِي الأَرْض فَسادًا﴾ أيْ مُفْسِدِينَ بِالمَعاصِي ﴿واللَّه لا يُحِبّ المُفْسِدِينَ﴾ بِمَعْنى أنَّهُ يُعاقِبهُمْ"],[65,65,"﴿ولَوْ أنَّ أهْل الكِتاب آمَنُوا﴾ بِمُحَمَّدٍ ﷺ ﴿واتَّقَوْا﴾ الكُفْر"],[66,66,"﴿ولَوْ أنَّهُمْ أقامُوا التَّوْراة والإنْجِيل﴾ بِالعَمَلِ بِما فِيهِما ومِنهُ الإيمان بِالنَّبِيِّ ﷺ ﴿وما أُنْزِلَ إلَيْهِمْ﴾ مِن الكُتُب ﴿مِن رَبّهمْ لَأَكَلُوا مِن فَوْقهمْ ومِن تَحْت أرْجُلهمْ﴾ بِأَنْ يُوَسِّع عَلَيْهِمْ الرِّزْق ويُفِيض مِن كُلّ جِهَة ﴿مِنهُمْ أُمَّة﴾ جَماعَة ﴿مُقْتَصِدَة﴾ تَعْمَل بِهِ وهُمْ مَن آمَنَ بِالنَّبِيِّ ﷺ كَعَبْدِ اللَّه بْن سَلام وأَصْحابه ﴿وكَثِير مِنهُمْ ساءَ﴾ بِئْسَ ﴿ما﴾ شَيْئًا ﴿يَعْمَلُونَـ﴾ ـه"],[67,67,"﴿يا أيّها الرَّسُول بَلِّغْ﴾ جَمِيع ﴿ما أُنْزِلَ إلَيْك مِن رَبّك﴾ ولا تَكْتُم شَيْئًا مِنهُ خَوْفًا أنْ تُنال بِمَكْرُوهٍ ﴿وإنْ لَمْ تَفْعَل﴾ أيْ لَمْ تُبَلِّغ جَمِيع ما أُنْزِلَ إلَيْك ﴿فَما بَلَّغْت رِسالَته﴾ بِالإفْرادِ والجَمْع لِأَنَّ كِتْمان بَعْضها كَكِتْمانِ كُلّها ﴿واللَّه يَعْصِمك مِن النّاس﴾ أنْ يَقْتُلُوك وكانَ ﷺ يُحْرَس حَتّى نَزَلَتْ فَقالَ: \"انْصَرِفُوا فَقَدْ عَصَمَنِي اللَّه\" رَواهُ الحاكِم"],[68,68,"﴿قُلْ يا أهْل الكِتاب لَسْتُمْ عَلى شَيْء﴾ مِن الدِّين مُعْتَدّ بِهِ ﴿حَتّى تُقِيمُوا التَّوْراة والإنْجِيل وما أُنْزِلَ إلَيْكُمْ مِن رَبّكُمْ﴾ بِأَنْ تَعْمَلُوا بِما فِيهِ ومِنهُ الإيمان بِي ﴿ولَيَزِيدَن كَثِيرًا مِنهُمْ ما أُنْزِلَ إلَيْك مِن رَبّك﴾ مِن القُرْآن ﴿طُغْيانًا وكُفْرًا﴾ لِكُفْرِهِمْ بِهِ ﴿فَلا تَأْسَ﴾ تَحْزَن ﴿عَلى القَوْم الكافِرِينَ﴾ إنْ لَمْ يُؤْمِنُوا بِك أيْ لا تَهْتَمّ بِهِمْ"],[69,69,"﴿إنّ الَّذِينَ آمَنُوا والَّذِينَ هادُوا﴾ هُمْ اليَهُود مُبْتَدَأ ﴿والصّابِئُونَ﴾ فِرْقَة مِنهُمْ ﴿والنَّصارى﴾ ويُبْدَل مِن المُبْتَدَأ ﴿مَن آمَنَ﴾ مِنهُمْ ﴿بِاللَّهِ واليَوْم الآخِر وعَمِلَ صالِحًا فَلا خَوْف عَلَيْهِمْ ولا هُمْ يَحْزَنُونَ﴾ فِي الآخِرَة خَبَر المُبْتَدَأ ودالّ عَلى خَبَر إنّ"],[70,70,"﴿لَقَدْ أخَذْنا مِيثاق بَنِي إسْرائِيل﴾ عَلى الإيمان بِاللَّهِ ورُسُله ﴿وأَرْسَلْنا إلَيْهِمْ رُسُلًا كُلَّما جاءَهُمْ رَسُول﴾ مِنهُمْ ﴿بِما لا تَهْوى أنْفُسهمْ﴾ مِن الحَقّ كَذَّبُوهُ ﴿فَرِيقًا﴾ مِنهُمْ ﴿كَذَّبُوا وفَرِيقًا﴾ مِنهُمْ ﴿يَقْتُلُونَ﴾ كَزَكَرِيّا والتَّعْبِير بِهِ دُون قَتَلُوا حِكايَة لِلْحالِ الماضِيَة لِلْفاصِلَةِ"],[71,71,"﴿وحَسِبُوا﴾ ظَنُّوا أنْ ﴿لا تَكُون﴾ بِالرَّفْعِ فَأَنْ مُخَفَّفَة والنَّصْب فَهِيَ ناصِبَة أيْ تَقَع ﴿فِتْنَة﴾ عَذاب بِهِمْ عَلى تَكْذِيب الرُّسُل وقَتْلهمْ ﴿فَعَمُوا﴾ عَنْ الحَقّ فَلَمْ يُبْصِرُوهُ ﴿وصَمُّوا﴾ عَنْ اسْتِماعه ﴿ثُمَّ تابَ اللَّه عَلَيْهِمْ﴾ لَمّا تابُوا ﴿ثُمَّ عَمُوا وصَمُّوا﴾ ثانِيًا ﴿كَثِير مِنهُمْ﴾ بَدَل مِن الضَّمِير ﴿واللَّه بَصِير بِما يَعْمَلُونَ﴾ فَيُجازِيهِمْ بِهِ"],[72,72,"﴿لَقَدْ كَفَرَ الَّذِينَ قالُوا إنّ اللَّه هُوَ المَسِيح ابْن مَرْيَم﴾ سَبَقَ مِثْله ﴿وقالَ﴾ لَهُمْ ﴿المَسِيح يا بَنِي إسْرائِيل اُعْبُدُوا اللَّه رَبِّي ورَبّكُمْ﴾ فَإنِّي عَبْد ولَسْت بِإلَهٍ ﴿إنّهُ مَن يُشْرِك بِاللَّهِ﴾ فِي العِبادَة غَيْره ﴿فَقَدْ حَرَّمَ اللَّه عَلَيْهِ الجَنَّة﴾ مَنَعَهُ أنْ يَدْخُلها ﴿ومَأْواهُ النّار وما لِلظّالِمِينَ مِن﴾ زائِدَة ﴿أنْصار﴾ يَمْنَعُونَهُمْ مِن عَذاب اللَّه"],[73,73,"﴿لَقَدْ كَفَرَ الَّذِينَ قالُوا إنّ اللَّه ثالِث﴾ آلِهَة ﴿ثَلاثَة﴾ أيْ أحَدها والآخَرانِ عِيسى وأُمّه وهُمْ فِرْقَة مِن النَّصارى ﴿وما مِن إلَه إلّا إلَه واحِد وإنْ لَمْ يَنْتَهُوا عَمّا يَقُولُونَ﴾ مِن التَّثْلِيث ويُوَحِّدُوا ﴿لَيَمَسَّن الَّذِينَ كَفَرُوا﴾ أيْ ثَبَتُوا عَلى الكُفْر ﴿مِنهُمْ عَذاب ألِيم﴾ مُؤْلِم وهُوَ النّار"],[74,74,"﴿أفَلا يَتُوبُونَ إلى اللَّه ويَسْتَغْفِرُونَه﴾ مِمّا قالُوا اسْتِفْهام تَوْبِيخ ﴿واللَّه غَفُور﴾ لِمَن تابَ ﴿رَحِيم﴾ بِهِ"],[75,75,"﴿خَلَتْ﴾ مَضَتْ ﴿مِن قَبْله الرُّسُل﴾ فَهُوَ يُمْضِي مِثْلهمْ ولَيْسَ بِإلَهٍ كَما زَعَمُوا وإلّا لَما مَضى ﴿وأُمّه صِدِّيقَة﴾ مُبالَغَة فِي الصِّدْق ﴿كانا يَأْكُلانِ الطَّعام﴾ كَغَيْرِهِما مِن النّاس ومَن كانَ كَذَلِكَ لا يَكُون إلَهًا لِتَرْكِيبِهِ وضَعْفه وما يَنْشَأ مِنهُ مِن البَوْل والغائِط ﴿اُنْظُرْ﴾ مُتَعَجِّبًا ﴿كَيْفَ نُبَيِّن لَهُمْ الآيات﴾ عَلى وحْدانِيّتنا ﴿ثُمَّ اُنْظُرْ أنّى﴾ كَيْفَ ﴿يُؤْفَكُونَ﴾ يُصْرَفُونَ عَنْ الحَقّ مَعَ قِيام البُرْهان"],[76,76,"﴿قُلْ أتَعْبُدُونَ مِن دُون اللَّه﴾ أيْ غَيْره ﴿ما لا يَمْلِك لَكُمْ ضَرًّا ولا نَفْعًا واللَّه هُوَ السَّمِيع﴾ لِأَقْوالِكُمْ ﴿العَلِيم﴾ بِأَحْوالِكُمْ والِاسْتِفْهام لِلْإنْكارِ"],[77,77,"﴿قُلْ يا أهْل الكِتاب﴾ اليَهُود والنَّصارى ﴿لا تَغْلُوا﴾ تُجاوِزُوا الحَدّ ﴿فِي دِينكُمْ﴾ غُلُوًّا ﴿غَيْر الحَقّ﴾ بِأَنْ تَضَعُوا عِيسى أوْ تَرْفَعُوهُ فَوْق حَقّه ﴿ولا تَتَّبِعُوا أهْواء قَوْم قَدْ ضَلُّوا مِن قَبْل﴾ بِغُلُوِّهِمْ وهُمْ أسْلافهمْ ﴿وأَضَلُّوا كَثِيرًا﴾ مِن النّاس ﴿وضَلُّوا عَنْ سَواء السَّبِيل﴾ عَنْ طَرِيق الحَقّ والسَّواء فِي الأَصْل الوَسَط"],[78,78,"﴿لُعِنَ الَّذِينَ كَفَرُوا مِن بَنِي إسْرائِيل عَلى لِسان داود﴾ بِأَنْ دَعا عَلَيْهِمْ فَمُسِخُوا قِرَدَة وهُمْ أصْحاب أيْلَة ﴿وعِيسى ابْن مَرْيَم﴾ بِأَنْ دَعا عَلَيْهِمْ فَمُسِخُوا خَنازِير وهُمْ أصْحاب المائِدَة ﴿ذَلِكَ﴾ اللَّعْن"],[79,79,"﴿كانُوا لا يَتَناهَوْنَ﴾ أيْ لا يَنْهى بَعْضهمْ بَعْضًا ﴿عَنْ﴾ مُعاوَدَة ﴿مُنْكَر فَعَلُوهُ لَبِئْسَ ما كانُوا يَفْعَلُونَ﴾ فِعْلهمْ هَذا"],[80,80,"﴿تَرى﴾ يا مُحَمَّد ﴿كَثِيرًا مِنهُمْ يَتَوَلَّوْنَ الَّذِينَ كَفَرُوا﴾ مِن أهْل مَكَّة بُغْضًا لَك ﴿لَبِئْسَ ما قَدَّمَتْ لَهُمْ أنْفُسهمْ﴾ مِن العَمَل لِمَعادِهِمْ المُوجِب لَهُمْ"],[81,81,"﴿ولَوْ كانُوا يُؤْمِنُونَ بِاللَّهِ والنَّبِيّ﴾ مُحَمَّد ﴿وما أُنْزِلَ إلَيْهِ ما اتَّخَذُوهُمْ﴾ أيْ الكُفّار ﴿أوْلِياء ولَكِنَّ كَثِيرًا مِنهُمْ فاسِقُونَ﴾ خارِجُونَ عَنْ الإيمان"],[82,82,"﴿لَتَجِدَن﴾ يا مُحَمَّد ﴿أشَدّ النّاس عَداوَة لِلَّذِينَ آمَنُوا اليَهُود والَّذِينَ أشْرَكُوا﴾ مِن أهْل مَكَّة لِتَضاعُفِ كُفْرهمْ وجَهْلهمْ وانْهِماكهمْ فِي اتِّباع الهَوى ﴿ولَتَجِدَن أقْرَبهمْ مَوَدَّة لِلَّذِينَ آمَنُوا الَّذِينَ قالُوا إنّا نَصارى ذَلِكَ﴾ أيْ قُرْب مَوَدَّتهمْ لِلْمُؤْمِنِينَ ﴿بِأَنَّ﴾ بِسَبَبِ أنَّ ﴿مِنهُمْ قِسِّيسِينَ﴾ عُلَماء ﴿ورُهْبانًا﴾ عُبّادًا ﴿وأَنَّهُمْ لا يَسْتَكْبِرُونَ﴾ عَنْ اتِّباع الحَقّ كَما يَسْتَكْبِر اليَهُود وأَهْل مَكَّة، نَزَلَتْ فِي وفْد النَّجاشِيّ القادِمِينَ عَلَيْهِ مِن الحَبَشَة قَرَأَ ﷺ سُورَة يس فَبَكَوْا وأَسْلَمُوا وقالُوا ما أشْبَه هَذا بِما كانَ يَنْزِل عَلى عِيسى"],[83,83,"﴿وإذا سَمِعُوا ما أُنْزِلَ إلى الرَّسُول﴾ مِن القُرْآن ﴿تَرى أعْيُنهمْ تَفِيض مِن الدَّمْع مِمّا عَرَفُوا مِن الحَقّ يَقُولُونَ رَبّنا آمَنّا﴾ صَدَّقْنا بِنَبِيِّك وكِتابك ﴿فاكْتُبْنا مَعَ الشّاهِدِينَ﴾ المُقَرَّبِينَ بِتَصْدِيقِهِمْ"],[84,84,"﴿و﴾ قالُوا فِي جَواب مَن عَيَّرَهُمْ بِالإسْلامِ مِن اليَهُود ﴿ما لَنا لا نُؤْمِن بِاللَّهِ وما جاءَنا مِن الحَقّ﴾ القُرْآن أيْ لا مانِع لَنا مِن الإيمان مَعَ وُجُود مُقْتَضِيه ﴿ونَطْمَع﴾ عُطِفَ عَلى نُؤْمِن ﴿أنْ يُدْخِلنا رَبّنا مَعَ القَوْم الصّالِحِينَ﴾ المُؤْمِنِينَ الجَنَّة"],[85,85,"﴿فَأَثابَهُمْ اللَّه بِما قالُوا جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها وذَلِك جَزاء المُحْسِنِينَ﴾ بِالإيمانِ"],[87,87,"ونَزَلَ لَمّا هَمَّ قَوْم مِن الصَّحابَة أنْ يُلازِمُوا الصَّوْم والقِيام ولا يَقْرَبُوا النِّساء والطِّيب ولا يَأْكُلُوا اللَّحْم ولا يَنامُوا عَلى الفِراش ﴿يا أيّها الَّذِينَ آمَنُوا لا تُحَرِّمُوا طَيِّبات ما أحَلَّ اللَّه لَكُمْ ولا تَعْتَدُوا﴾ تَتَجاوَزُوا أمْر اللَّه"],[88,88,"﴿وكُلُوا مِمّا رَزَقَكُمْ اللَّه حَلالًا طَيِّبًا﴾ مَفْعُول والجارّ والمَجْرُور قَبْله حال مُتَعَلِّق بِهِ"],[89,89,"﴿لا يُؤاخِذكُمْ اللَّه بِاللَّغْوِ﴾ الكائِن ﴿فِي أيْمانكُمْ﴾ هُوَ ما يَسْبِق إلَيْهِ اللِّسان مِن غَيْر قَصْد الحَلِف كَقَوْلِ الإنْسان: لا واللَّه وبَلى واللَّه ﴿ولَكِنْ يُؤاخِذكُمْ بِما عَقَدْتُمْ﴾ بِالتَّخْفِيفِ والتَّشْدِيد وفِي قِراءَة عاقَدْتُمْ ﴿الأَيْمان﴾ عَلَيْهِ بِأَنْ حَلَفْتُمْ عَنْ قَصْد ﴿فَكَفّارَته﴾ أيْ اليَمِين إذا حَنِثْتُمْ فِيهِ ﴿إطْعام عَشَرَة مَساكِين﴾ لِكُلِّ مِسْكِين مُدّ ﴿مِن أوْسَط ما تُطْعِمُونَ أهْلِيكُمْ﴾ مِنهُ أيْ أقْصَدُهُ وأَغْلَبه لا أعْلاهُ ولا أدْناهُ ﴿أوْ كِسْوَتهمْ﴾ بِما يُسَمّى كِسْوَة كَقَمِيصٍ وعِمامَة وإزار ولا يَكْفِي دَفْع ما ذُكِرَ إلى مِسْكِين واحِد وعَلَيْهِ الشّافِعِيّ ﴿أوْ تَحْرِير﴾ عِتْق ﴿رَقَبَة﴾ أيْ مُؤْمِنَة كَما فِي كَفّارَة القَتْل والظِّهار حَمْلًا لِلْمُطْلَقِ عَلى المُقَيَّد ﴿فَمَن لَمْ يَجِد﴾ واحِدًا مِمّا ذُكِرَ ﴿فَصِيام ثَلاثَة أيّام﴾ كَفّارَته وظاهِره أنَّهُ لا يُشْتَرَط التَّتابُع وعَلَيْهِ الشّافِعِيّ ﴿ذَلِكَ﴾ المَذْكُور ﴿كَفّارَة أيْمانكُمْ إذا حَلَفْتُمْ﴾ وحَنِثْتُمْ ﴿واحْفَظُوا أيْمانكُمْ﴾ أنْ تَنْكُثُوها ما لَمْ تَكُنْ عَلى فِعْل بِرّ أوْ إصْلاح بَيْن النّاس كَما فِي سُورَة البَقَرَة ﴿كَذَلِكَ﴾ أيْ مِثْل ما بُيِّنَ لَكُمْ ما ذُكِرَ ﴿يُبَيِّن اللَّه لَكُمْ آياته لَعَلَّكُمْ تَشْكُرُونَ﴾ ـهُ عَلى ذَلِكَ"],[90,90,"﴿يا أيّها الَّذِينَ آمَنُوا إنّما الخَمْر﴾ المُسْكِر الَّذِي يُخامِر العَقْل ﴿والمَيْسِر﴾ القِمار ﴿والأَنْصاب﴾ الأَصْنام ﴿والأَزْلام﴾ قِداح الِاسْتِقْسام ﴿رِجْس﴾ خَبِيث مُسْتَقْذَر ﴿مِن عَمَل الشَّيْطان﴾ الَّذِي يُزَيِّنهُ ﴿فاجْتَنِبُوهُ﴾ أيْ الرِّجْس المُعَبَّر عَنْ هَذِهِ الأَشْياء أنْ تَفْعَلُوهُ"],[91,91,"﴿إنّما يُرِيد الشَّيْطان أنْ يُوقِع بَيْنكُمْ العَداوَة والبَغْضاء فِي الخَمْر والمَيْسِر﴾ إذْ أتَيْتُمُوهُما لِما يَحْصُل فِيهِما مِن الشَّرّ والفِتَن ﴿ويَصُدّكُمْ﴾ بِالِاشْتِغالِ بِهِما ﴿عَنْ ذِكْر اللَّه وعَنْ الصَّلاة﴾ خَصَّها بِالذِّكْرِ تَعْظِيمًا لَها ﴿فَهَلْ أنْتُمْ مُنْتَهُونَ﴾ عَنْ إتْيانهما أيْ انْتَهُوا"],[92,92,"﴿وأَطِيعُوا اللَّه وأَطِيعُوا الرَّسُول واحْذَرُوا﴾ المَعاصِي ﴿فَإنْ تَوَلَّيْتُمْ﴾ عَنْ الطّاعَة ﴿فاعْلَمُوا أنَّما عَلى رَسُولنا البَلاغ المُبِين﴾ الإبْلاغ البَيِّن وجَزاؤُكُمْ عَلَيْنا"],[93,93,"﴿لَيْسَ عَلى الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحات جُناح فِيما طَعِمُوا﴾ أكَلُوا مِن الخَمْر والمَيْسِر قَبْل التَّحْرِيم ﴿إذا ما اتَّقَوْا﴾ المُحَرَّمات ﴿وآمَنُوا وعَمِلُوا الصّالِحات ثُمَّ اتَّقَوْا وآمَنُوا﴾ ثَبَتُوا عَلى التَّقْوى والإيمان ﴿ثُمَّ اتَّقَوْا وأَحْسَنُوا﴾ العَمَل ﴿واللَّه يُحِبّ المُحْسِنِينَ﴾ بِمَعْنى أنَّهُ يُثِيبهُمْ"],[94,94,"﴿يا أيّها الَّذِينَ آمَنُوا لَيَبْلُوَنكُمْ﴾ لَيَخْتَبِرَنكُمْ ﴿اللَّه بِشَيْءٍ﴾ يُرْسِلهُ لَكُمْ ﴿مِن الصَّيْد تَنالهُ﴾ أيْ الصِّغار مِنهُ ﴿أيْدِيكُمْ ورِماحكُمْ﴾ الكِبار مِنهُ وكانَ ذَلِكَ بِالحُدَيْبِيَةِ وهُمْ مُحْرِمُونَ فَكانَتْ الوَحْش والطَّيْر تَغْشاهُمْ فِي رِحالهمْ ﴿لِيَعْلَم اللَّه﴾ عِلْم ظُهُور ﴿مَن يَخافهُ بِالغَيْبِ﴾ حال أيْ غائِبًا لَمْ يَرَهُ فَيَجْتَنِب الصَّيْد ﴿فَمَن اعْتَدى بَعْد ذَلِكَ﴾ النَّهْي عَنْهُ فاصْطادَهُ"],[95,95,"﴿يا أيّها الَّذِينَ آمَنُوا لا تَقْتُلُوا الصَّيْد وأَنْتُمْ حُرُم﴾ مُحْرِمُونَ بِحَجٍّ أوْ عُمْرَة ﴿ومَن قَتَلَهُ مِنكُمْ مُتَعَمِّدًا فَجَزاء﴾ بِالتَّنْوِينِ ورُفِعَ ما بَعْده أيْ فَعَلَيْهِ جَزاء هُوَ ﴿مِثْل ما قَتَلَ مِن النَّعَم﴾ أيْ شَبَهه فِي الخِلْقَة وفِي قِراءَة بِإضافَةِ جَزاء ﴿يَحْكُم بِهِ﴾ أيْ بِالمِثْلِ رَجُلانِ ﴿ذَوا عَدْل مِنكُمْ﴾ لَهُما فِطْنَة يُمَيِّزانِ بِها أشْبَه الأَشْياء بِهِ وقَدْ حَكَمَ ابْن عَبّاس وعُمَر وعَلِيّ رَضِيَ اللَّه عَنْهُمْ فِي النَّعامَة بِبَدَنَةٍ وابْن عَبّاس وأَبُو عُبَيْدَة فِي بَقَر الوَحْش وحِماره بِبَقَرَةٍ وابْن عُمَر وابْن عَوْف فِي الظَّبْي بِشاةٍ وحَكَمَ بِها ابْن عَبّاس وعُمَر وغَيْرهما فِي الحَمام لِأَنَّهُ يُشْبِهها فِي العَبّ ﴿هَدْيًا﴾ حال مِن جَزاء ﴿بالِغ الكَعْبَة﴾ أيْ يَبْلُغ بِهِ الحَرَم فَيُذْبَح فِيهِ ويَتَصَدَّق بِهِ عَلى مَساكِينه ولا يَجُوز أنْ يُذْبَح حَيْثُ كانَ ونَصْبه نَعْتًا لِما قَبْله وإنْ أُضِيف لِأَنَّ إضافَته لَفْظِيَّة لا تُفِيد تَعْرِيفًا فَإنْ لَمْ يَكُنْ لِلصَّيْدِ مِثْل مِن النَّعَم كالعُصْفُورِ والجَراد فَعَلَيْهِ قِيمَته ﴿أوْ﴾ عَلَيْهِ ﴿كَفّارَة﴾ غَيْر الجَزاء وإنْ وجَدَهُ هِيَ ﴿طَعام مَساكِين﴾ مِن غالِب قُوت البَلَد ما يُساوِي قِيمَة الجَزاء لِكُلِّ مِسْكِين مُدّ وفِي قِراءَة بِإضافَةِ كَفّارَة لِما بَعْده وهِيَ لِلْبَيانِ ﴿أوْ﴾ عَلَيْهِ ﴿عَدْل﴾ مِثْل ﴿ذَلِكَ﴾ الطَّعام ﴿صِيامًا﴾ يَصُومهُ عَنْ كُلّ مُدّ يَوْم وإنْ وجَدَهُ وجَبَ ذَلِكَ عَلَيْهِ ﴿لِيَذُوقَ وبال﴾ ثِقَل جَزاء ﴿أمْره﴾ الَّذِي فَعَلَهُ ﴿عَفا اللَّه عَمّا سَلَف﴾ مِن قَتْل الصَّيْد قَبْل تَحْرِيمه ﴿ومَن عادَ﴾ إلَيْهِ ﴿فَيَنْتَقِم اللَّه مِنهُ واللَّه عَزِيز﴾ غالِب عَلى أمْره ﴿ذُو انْتِقام﴾ مِمَّنْ عَصاهُ وأُلْحِق بِقَتْلِهِ مُتَعَمِّدًا فِيما ذُكِرَ الخَطَأ"],[96,96,"﴿أُحِلَّ لَكُمْ﴾ أيّها النّاس حَلالًا كُنْتُمْ أوْ مُحْرِمِينَ ﴿صَيْد البَحْر﴾ أنْ تَأْكُلُوهُ وهُوَ ما لا يَعِيش إلّا فِيهِ كالسَّمَكِ بِخِلافِ ما يَعِيش فِيهِ وفِي البَرّ كالسَّرَطانِ ﴿وطَعامه﴾ ما يَقْذِفهُ مَيِّتًا ﴿مَتاعًا﴾ تَمْتِيعًا ﴿لَكُمْ﴾ تَأْكُلُونَهُ ﴿ولِلسَّيّارَةِ﴾ المُسافِرِينَ مِنكُمْ يَتَزَوَّدُونَهُ ﴿وحُرِّمَ عَلَيْكُمْ صَيْد البَرّ﴾ وهُوَ ما يَعِيش فِيهِ مِن الوَحْش المَأْكُول أنْ تَصِيدُوهُ ﴿ما دُمْتُمْ حُرُمًا﴾ فَلَوْ صادَهُ حَلال فَلِلْمُحْرِمِ أكْله كَما بَيَّنَتْهُ السُّنَّة"],[97,97,"﴿جَعَلَ اللَّه الكَعْبَة البَيْت الحَرام﴾ المُحَرَّم ﴿قِيامًا لِلنّاسِ﴾ يَقُوم بِهِ أمْر دِينهمْ بِالحَجِّ إلَيْهِ ودُنْياهُمْ بِأَمْنِ داخِله وعَدَم التَّعَرُّض لَهُ وجَبْي ثَمَرات كُلّ شَيْء إلَيْهِ وفِي قِراءَة قَيِّمًا بِلا ألِف مَصْدَر قامَ غَيْر مُعَلّ ﴿والشَّهْر الحَرام﴾ بِمَعْنى الأَشْهُر الحُرُم ذُو القَعْدَة وذُو الحِجَّة والمُحَرَّم ورَجَب قِيامًا لَهُمْ بِأَمْنِهِمْ مِن القِتال فِيها. ﴿والهَدْي والقَلائِد﴾ قِيامًا لَهُمْ بِأَمْنِ صاحِبهما مِن التَّعَرُّض لَهُ ﴿ذَلِكَ﴾ الجَعْل المَذْكُور ﴿لِتَعْلَمُوا أنَّ اللَّه يَعْلَم ما فِي السَّماوات وما فِي الأَرْض وأَنَّ اللَّه بِكُلِّ شَيْء عَلِيم﴾ فَإنَّ جَعْله ذَلِكَ لِجَلْبِ المَصالِح لَكُمْ ودَفْع المَضارّ عَنْكُمْ قَبْل وُقُوعها دَلِيل عَلى عِلْمه بِما هُوَ فِي الوُجُود وما هُوَ كائِن"],[98,98,"﴿اعْلَمُوا أنَّ اللَّه شَدِيد العِقاب﴾ لِأَعْدائِهِ ﴿وأَنَّ اللَّه غَفُور﴾ لِأَوْلِيائِهِ ﴿رَحِيم﴾ بِهِمْ"],[99,99,"﴿ما عَلى الرَّسُول إلّا البَلاغ﴾ لَكُمْ ﴿واللَّه يَعْلَم ما تُبْدُونَ﴾ تُظْهِرُونَ مِن العَمَل ﴿وما تَكْتُمُونَ﴾ تُخْفُونَ مِنهُ فَيُجازِيكُمْ بِهِ"],[100,100,"﴿قُلْ لا يَسْتَوِي الخَبِيث﴾ الحَرام ﴿والطَّيِّب﴾ الحَلال ﴿ولَوْ أعْجَبَك﴾ أيْ سَرَّك ﴿كَثْرَة الخَبِيث فاتَّقُوا اللَّه﴾ فِي تَرْكه ﴿يا أُولِي الأَلْباب لَعَلَّكُمْ تُفْلِحُونَ﴾ تَفُوزُونَ"],[101,101,"ونَزَلَ لَمّا أكْثَرُوا سُؤاله ﷺ ﴿يا أيّها الَّذِينَ آمَنُوا لا تَسْأَلُوا عَنْ أشْياء إنْ تُبْدَ﴾ تُظْهَر ﴿لَكُمْ تَسُؤْكُمْ﴾ لِما فِيها مِن المَشَقَّة ﴿وإنْ تَسْأَلُوا عَنْها حِين يُنَزَّل القُرْآن﴾ فِي زَمَن النَّبِيّ ﷺ ﴿تُبْدَ لَكُمْ﴾ المَعْنى إذا سَأَلْتُمْ عَنْ أشْياء فِي زَمَنه يَنْزِل القُرْآن بِإبْدائِها ومَتى أبْداها ساءَتْكُمْ فَلا تَسْأَلُوا عَنْها قَدْ ﴿عَفا اللَّه عَنْها﴾ عَنْ مَسْأَلَتكُمْ فَلا تَعُودُوا"],[102,102,"﴿قَدْ سَأَلَها﴾ أيْ الأَشْياء ﴿قَوْم مِن قَبْلكُمْ﴾ أنْبِياءَهُمْ فَأَجِيبُوا بِبَيانِ أحْكامها ﴿ثُمَّ أصْبَحُوا﴾ صارُوا ﴿بِها كافِرِينَ﴾ بِتَرْكِهِمْ العَمَل بِها"],[103,103,"﴿ما جَعَلَ﴾ شَرَعَ ﴿اللَّه مِن بَحِيرَة ولا سائِبَة ولا وصِيلَة ولا حامٍ﴾ كَما كانَ أهْل الجاهِلِيَّة يَفْعَلُونَهُ رَوى البُخارِيّ عَنْ سَعِيد بْن المُسَيِّب قالَ: البَحِيرَة الَّتِي يُمْنَح دَرّها لِلطَّواغِيتِ فَلا يَحْلُبها أحَد مِن النّاس والسّائِبَة الَّتِي كانُوا يُسَيِّبُونَها لِآلِهَتِهِمْ فَلا يُحْمَل عَلَيْها شَيْء والوَصِيلَة النّاقَة البِكْر تُبْكِر فِي أوَّل نِتاج الإبِل بِأُنْثى ثُمَّ تُثْنِي بَعْد بِأُنْثى وكانُوا يُسَيِّبُونَها لِطَواغِيتِهِمْ إنْ وصَلَتْ إحْداهُما بِأُخْرى لَيْسَ بَيْنهما ذَكَر والحام فَحْل الإبِل يَضْرِب الضِّراب المَعْدُودَة فَإذا قَضى ضِرابه ودَعُوهُ لِلطَّواغِيتِ وأَعْفَوْهُ مِن أنْ يُحْمَل عَلَيْهِ شَيْء وسَمَّوْهُ الحامِي ﴿ولَكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلى اللَّه الكَذِب﴾ فِي ذَلِكَ وفِي نِسْبَته إلَيْهِ ﴿وأَكْثَرهمْ لا يَعْقِلُونَ﴾ أنَّ ذَلِكَ افْتِراء لِأَنَّهُمْ قَلَّدُوا فِيهِ آباءَهُمْ"],[104,104,"﴿وإذا قِيلَ لَهُمْ تَعالَوْا إلى ما أنْزَلَ اللَّه وإلى الرَّسُول﴾ أيْ إلى حُكْمه مِن تَحْلِيل ما حَرَّمْتُمْ ﴿قالُوا حَسْبنا﴾ كافِينا ﴿ما وجَدْنا عَلَيْهِ آباءَنا﴾ مِن الدِّين والشَّرِيعَة ﴿أوَلَوْ﴾ حَسْبهمْ ذَلِكَ ﴿كانَ آباؤُهُمْ لا يَعْلَمُونَ شَيْئًا ولا يَهْتَدُونَ﴾ إلى الحَقّ والِاسْتِفْهام لِلْإنْكارِ"],[105,105,"﴿يا أيّها الَّذِينَ آمَنُوا عَلَيْكُمْ أنْفُسكُمْ﴾ أيْ احْفَظُوها وقُومُوا بِصَلاحِها ﴿لا يَضُرّكُمْ مَن ضَلَّ إذا اهْتَدَيْتُمْ﴾ قِيلَ المُراد لا يَضُرّكُمْ مَن ضَلَّ مِن أهْل الكِتاب وقِيلَ المُراد غَيْرهمْ لِحَدِيثِ أبِي ثَعْلَبَة الخُشَنِيّ: سَأَلْت عَنْها رَسُول اللَّه ﷺ فَقالَ: \"ائْتَمِرُوا بِالمَعْرُوفِ وتَناهَوْا عَنْ المُنْكَر حَتّى إذا رَأَيْت شُحًّا مُطاعًا وهَوًى مُتَّبَعًا ودُنْيا مُؤْثَرَة وإعْجاب كُلّ ذِي رَأْي بِرَأْيِهِ فَعَلَيْك نَفْسك\" رَواهُ الحاكِم وغَيْره ﴿إلى اللَّه مَرْجِعكُمْ جَمِيعًا فَيُنَبِّئكُمْ بِما كُنْتُمْ تَعْمَلُونَ﴾ فَيُجازِيكُمْ بِهِ"],[106,106,"﴿يا أيّها الَّذِينَ آمَنُوا شَهادَة بَيْنكُمْ إذا حَضَرَ أحَدكُمْ المَوْت﴾ أيْ أسْبابه ﴿حِين الوَصِيَّة اثْنانِ ذَوا عَدْل مِنكُمْ﴾ خَبَر بِمَعْنى الأَمْر أيْ لِيَشْهَد وإضافَة شَهادَة لَبَيِّن عَلى الِاتِّساع وحِين بَدَل مِن إذا أوْ ظَرْف لحَضَرَ ﴿أوْ آخَرانِ مِن غَيْركُمْ﴾ أيْ غَيْر مِلَّتكُمْ ﴿إنْ أنْتُمْ ضَرَبْتُمْ﴾ سافَرْتُمْ ﴿فِي الأَرْض فَأَصابَتْكُمْ مُصِيبَة المَوْت تَحْبِسُونَهُما﴾ تُوقِفُونَهُما صِفَة آخَرانِ ﴿مِن بَعْد الصَّلاة﴾ أيْ صَلاة العَصْر ﴿فَيُقْسِمانِ﴾ يَحْلِفانِ ﴿بِاللَّهِ إنْ ارْتَبْتُمْ﴾ شَكَكْتُمْ فِيها ويَقُولانِ ﴿لا نَشْتَرِي بِهِ﴾ بِاللَّهِ ﴿ثَمَنًا﴾ عِوَضًا نَأْخُذهُ بَدَله مِن الدُّنْيا بِأَنْ نَحْلِف بِهِ أوْ نَشْهَد كَذِبًا لِأَجْلِهِ ﴿ولَوْ كانَ﴾ المُقْسَم لَهُ أوْ المَشْهُود لَهُ ﴿ذا قُرْبى﴾ قَرابَة مِنّا ﴿ولا نَكْتُم شَهادَة اللَّه﴾ الَّتِي أُمِرْنا بِها ﴿إنّا إذًا﴾ إنْ كَتَمْناها"],[107,107,"﴿فَإنْ عُثِرَ﴾ اُطُّلِعَ بَعْد حَلِفهما ﴿عَلى أنَّهُما اسْتَحَقّا إثْمًا﴾ أيْ فِعْلًا ما يُوجِبهُ مِن خِيانَة أوْ كَذِب فِي الشَّهادَة بِأَنْ وُجِدَ عِنْدهما مِثْلا ما اُتُّهِما بِهِ وادَّعَيا أنَّهُما ابْتاعاهُ مِن المَيِّت أوْ وصّى لَهُما بِهِ ﴿فَآخَرانِ يَقُومانِ مَقامهما﴾ فِي تَوَجُّه اليَمِين عَلَيْهِما ﴿مِن الَّذِينَ اسْتَحَقَّ عَلَيْهِمْ﴾ الوَصِيَّة وهُمْ الوَرَثَة ويُبْدَل مِن آخَرانِ ﴿الأَوْلَيانِ﴾ بِالمَيِّتِ أيْ الأَقْرَبانِ إلَيْهِ وفِي قِراءَة الأَوَّلَيْنِ جَمْع أوَّل صِفَة أوْ بَدَل مِن الَّذِينَ ﴿فَيُقْسِمانِ بِاللَّهِ﴾ عَلى خِيانَة الشّاهِدَيْنِ ويَقُولانِ ﴿لَشَهادَتنا﴾ يَمِيننا ﴿أحَقّ﴾ أصْدَق ﴿مِن شَهادَتهما﴾ يَمِينهما ﴿وما اعْتَدَيْنا﴾ تَجاوَزْنا الحَقّ فِي اليَمِين ﴿إنّا إذًا لَمِن الظّالِمِينَ﴾ المَعْنى لِيُشْهِد المُحْتَضِر عَلى وصِيَّته اثْنَيْنِ أوْ يُوصِي إلَيْهِما مِن أهْل دِينه أوْ غَيْرهمْ إنْ فَقَدَهُمْ لِسَفَرٍ ونَحْوه فَإنْ ارْتابَ الوَرَثَة فِيهِما فادَّعَوْا أنَّهُما خانا بِأَخْذِ شَيْء أوْ دَفْعه إلى شَخْص زَعَما أنَّ المَيِّت أوْصى لَهُ بِهِ فَلْيَحْلِفا إلى آخِره فَإنْ اطَّلَعَ عَلى أمارَة تَكْذِيبهما فادَّعَيا دافِعًا لَهُ حَلَفَ أقْرَب الوَرَثَة عَلى كَذِبهما وصَدَّقَ ما ادَّعَوْهُ والحُكْم ثابِت فِي الوَصِيَّيْنِ مَنسُوخ فِي الشّاهِدَيْنِ وكَذا شَهادَة غَيْر أهْل المِلَّة مَنسُوخَة واعْتِبار صَلاة العَصْر لِلتَّغْلِيظِ وتَخْصِيص الحَلِف فِي الآيَة بِاثْنَيْنِ مِن أقْرَب الوَرَثَة لِخُصُوصِ الواقِعَة الَّتِي نَزَلَتْ لَها وهِيَ ما رَواهُ البُخارِيّ أنَّ رَجُلًا مِن بَنِي سَهْم خَرَجَ مَعَ تَمِيم الدّارِيّ وعَدِيّ بْن بُداء أيْ وهُما نَصْرانِيّانِ، فَماتَ السَّهْمِيّ بِأَرْضٍ لَيْسَ فِيها مُسْلِم فَلَمّا قَدِما بِتَرِكَتِهِ فَقَدُوا جامًا مِن فِضَّة مُخَوَّصًا بِالذَّهَبِ فَرُفِعا إلى النَّبِيّ ﷺ فَنَزَلَتْ فَأَحْلَفَهُما ثُمَّ وُجِدَ الجام بِمَكَّة فَقالُوا ابْتَعْناهُ مِن تَمِيم وعَدِيّ فَنَزَلَتْ الآيَة الثّانِيَة فَقامَ رَجُلانِ مِن أوْلِياء السَّهْمِيّ فَحَلَفا، وفِي رِوايَة التِّرْمِذِيّ فَقامَ عَمْرو بْن العاصِ ورَجُل آخَر مِنهُمْ فَحَلَفا وكانَ أقْرَب إلَيْهِ وفِي رِوايَة فَمَرِضَ فَأَوْصى إلَيْهِما وأَمَرَهُما أنْ يَبْلُغا ما تَرَكَ أهْله فَلَمّا ماتَ أخَذا الجام ودَفَعا إلى أهْله ما بَقِيَ"],[108,108,"﴿ذَلِكَ﴾ الحُكْم المَذْكُور مِن رَدّ اليَمِين عَلى الوَرَثَة ﴿أدْنى﴾ أقْرَب إلى ﴿أنْ يَأْتُوا﴾ أيْ الشُّهُود أوْ الأَوْصِياء ﴿بِالشَّهادَةِ عَلى وجْهها﴾ الَّذِي تَحَمَّلُوها عَلَيْهِ مِن غَيْر تَحْرِيف ولا خِيانَة ﴿أوْ﴾ أقْرَب إلى أنْ ﴿يَخافُوا أنْ تُرَدّ أيْمان بَعْد أيْمانهمْ﴾ عَلى الوَرَثَة المُدَّعِينَ فَيَحْلِفُونَ عَلى خِيانَتهمْ وكَذِبهمْ فَيَفْتَضِحُونَ ويَغْرَمُونَ فَلا يَكْذِبُوا ﴿واتَّقُوا اللَّه﴾ بِتَرْكِ الخِيانَة والكَذِب ﴿واسْمَعُوا﴾ ما تُؤْمَرُونَ بِهِ سَماع قَبُول ﴿واللَّه لا يَهْدِي القَوْم الفاسِقِينَ﴾ الخارِجِينَ عَنْ طاعَته إلى سَبِيل الخَيْر"],[109,109,"﴿يَوْم يَجْمَع اللَّه الرُّسُل﴾ هُوَ يَوْم القِيامَة ﴿فَيَقُول﴾ لَهُمْ تَوْبِيخًا لِقَوْمِهِمْ ﴿ماذا﴾ أيْ الَّذِي ﴿أُجِبْتُمْ﴾ بِهِ حِين دَعَوْتُمْ إلى التَّوْحِيد ﴿قالُوا لا عِلْم لَنا﴾ بِذَلِكَ ﴿إنّك أنْت عَلّام الغُيُوب﴾ ما غابَ عَنْ العِباد وذَهَبَ عَنْهُمْ عِلْمه لِشِدَّةِ هَوْل يَوْم القِيامَة وفَزَعهمْ ثُمَّ يَشْهَدُونَ عَلى أُمَمهمْ لَمّا يَسْكُنُونَ"],[110,110,"اُذْكُرْ ﴿إذْ قالَ اللَّه يا عِيسى ابْن مَرْيَم اُذْكُرْ نِعْمَتِي عَلَيْك وعَلى والِدَتك﴾ بِشُكْرِها ﴿إذْ أيَّدْتُك﴾ قَوَّيْتُك ﴿بِرُوحِ القُدُس﴾ جِبْرِيل ﴿تُكَلِّم النّاس﴾ حال مِن الكاف فِي أيَّدْتُك ﴿فِي المَهْد﴾ أيْ طِفْلًا ﴿وكَهْلًا﴾ يُفِيد نُزُوله قَبْل السّاعَة لِأَنَّهُ رُفِعَ قَبْل الكُهُولَة كَما سَبَقَ فِي آل عِمْران ﴿وإذْ عَلَّمْتُك الكِتاب والحِكْمَة والتَّوْراة والإنْجِيل وإذْ تَخْلُق مِن الطِّين كَهَيْئَةِ﴾ كَصُورَةِ ﴿الطَّيْر﴾ والكاف اسْم بِمَعْنى مِثْل مَفْعُول ﴿بِإذْنِي فَتَنْفُخ فِيها فَتَكُون طَيْرًا بِإذْنِي﴾ بِإرادَتِي ﴿وتُبْرِئ الأَكْمَه والأَبْرَص بِإذْنِي وإذْ تُخْرِج المَوْتى﴾ مِن قُبُورهمْ أحْياء ﴿بِإذْنِي وإذْ كَفَفْت بَنِي إسْرائِيل عَنْك﴾ حِين هَمُّوا بِقَتْلِك ﴿إذْ جِئْتهمْ بِالبَيِّناتِ﴾ المُعْجِزات ﴿فَقالَ الَّذِينَ كَفَرُوا مِنهُمْ إنْ﴾ ما ﴿هَذا﴾ الَّذِي جِئْت بِهِ ﴿إلّا سِحْر مُبِين﴾ وفِي قِراءَة ساحِر أيْ عِيسى"],[111,111,"﴿وإذْ أوْحَيْت إلى الحَوارِيِّينَ﴾ أمَرْتهمْ عَلى لِسانه ﴿أنْ﴾ أيْ بِأَنْ ﴿آمِنُوا بِي وبِرَسُولِي﴾ عِيسى ﴿قالُوا آمَنّا﴾ بِهِما"],[112,112,"اُذْكُرْ ﴿إذْ قالَ الحَوارِيُّونَ يا عِيسى ابْن مَرْيَم هَلْ يَسْتَطِيع﴾ أيْ يَفْعَل ﴿رَبّك﴾ وفِي قِراءَة بالفَوْقانية ونُصِبَ ما بَعْده أيْ تَقْدِر أنْ تَسْأَلهُ ﴿أنْ يُنْزِل عَلَيْنا مائِدَة مِن السَّماء قالَ﴾ لَهُمْ عِيسى ﴿اتَّقُوا اللَّه﴾ فِي اقْتِراح الآيات"],[113,113,"﴿قالُوا نُرِيد﴾ سُؤالها مِن أجْل ﴿أنْ نَأْكُل مِنها وتَطْمَئِنّ﴾ تَسْكُن ﴿قُلُوبنا﴾ بِزِيادَةِ اليَقِين ﴿ونَعْلَم﴾ نَزْداد عِلْمًا ﴿أنْ﴾ مُخَفَّفَة أيْ أنَّك ﴿قَدْ صَدَقْتنا﴾ فِي ادِّعاء النُّبُوَّة"],[114,114,"﴿قالَ عِيسى ابْن مَرْيَم اللَّهُمَّ رَبّنا أنْزِل عَلَيْنا مائِدَة مِن السَّماء تَكُون لَنا﴾ أيْ يَوْم نُزُولها ﴿عِيدًا﴾ نُعَظِّمهُ ونُشَرِّفهُ ﴿لِأَوَّلِنا﴾ بَدَل مِن لَنا بِإعادَةِ الجارّ ﴿وآخِرنا﴾ مِمَّنْ يَأْتِي بَعْدنا ﴿وآيَة مِنك﴾ عَلى قُدْرَتك ونُبُوَّتِي ﴿وارْزُقْنا﴾ إيّاها"],[115,115,"﴿قالَ اللَّه﴾ مُسْتَجِيبًا لَهُ ﴿إنِّي مُنَزِّلُها﴾ بِالتَّخْفِيفِ والتَّشْدِيد ﴿عَلَيْكُمْ فَمَن يَكْفُر بَعْد﴾ أيْ بَعْد نُزُولها ﴿مِنكُمْ فَإنِّي أُعَذِّبهُ عَذابًا لا أُعَذِّبهُ أحَدًا مِن العالَمِينَ﴾ فَنَزَلَتْ المَلائِكَة بِها مِن السَّماء عَلَيْها سَبْعَة أرْغِفَة وسَبْعَة أحْوات فَأَكَلُوا مِنها حَتّى شَبِعُوا قالَهُ ابْن عَبّاس وفِي حَدِيث أُنْزِلَتْ المائِدَة مِن السَّماء خُبْزًا ولَحْمًا فَأُمِرُوا أنْ لا يَخُونُوا ولا يَدَّخِرُوا لِغَدٍ فَخانُوا وادَّخَرُوا فَمُسِخُوا قِرَدَة وخَنازِير"],[116,116,"﴿و﴾ اُذْكُرْ ﴿إذْ قالَ﴾ أيْ يَقُول ﴿اللَّه﴾ لِعِيسى فِي القِيامَة تَوْبِيخًا لِقَوْمِهِ ﴿يا عِيسى ابْن مَرْيَم أأَنْت قُلْت لِلنّاسِ اتَّخِذُونِي وأُمِّي إلَهَيْنِ مِن دُون اللَّه قالَ﴾ عِيسى وقَدْ أُرْعِدَ ﴿سُبْحانك﴾ تَنْزِيهًا لَك عَمّا لا يَلِيق بِك مِن شَرِيك وغَيْره ﴿ما يَكُون﴾ ما يَنْبَغِي ﴿لِي أنْ أقُول ما لَيْسَ لِي بِحَقٍّ﴾ خَبَر لَيْسَ ولِي لِلتَّبْيِينِ ﴿إنْ كُنْت قُلْته فَقَدْ عَلِمْته تَعْلَم ما﴾ أُخْفِيه ﴿فِي نَفْسِي ولا أعْلَم ما فِي نَفْسك﴾ أيْ ما تُخْفِيه مِن مَعْلُوماتك"],[117,117,"﴿ما قُلْت لَهُمْ إلّا ما أمَرْتنِي بِهِ﴾ وهُوَ ﴿أنْ اُعْبُدُوا اللَّه رَبِّي ورَبّكُمْ وكُنْت عَلَيْهِمْ شَهِيدًا﴾ رَقِيبًا أمْنَعهُمْ مِمّا يَقُولُونَ ﴿ما دُمْت فِيهِمْ فَلَمّا تَوَفَّيْتنِي﴾ قَبَضْتنِي بِالرَّفْعِ إلى السَّماء ﴿كُنْت أنْت الرَّقِيب عَلَيْهِمْ﴾ الحَفِيظ لِأَعْمالِهِمْ ﴿وأَنْت عَلى كُلّ شَيْء﴾ مِن قَوْلِي لَهُمْ وقَوْلهمْ بَعْدِي وغَيْر ذَلِكَ ﴿شَهِيد﴾ مُطَّلِع عالِم بِهِ"],[118,118,"﴿إنْ تُعَذِّبهُمْ﴾ أيْ مَن أقامَ عَلى الكُفْر مِنهُمْ ﴿فَإنَّهُمْ عِبادك﴾ وأَنْت مالِكهمْ تَتَصَرَّف فِيهِمْ كَيْفَ شِئْت لا اعْتِراض عَلَيْك ﴿وإنْ تَغْفِر لَهُمْ﴾ أيْ لِمَن آمَنَ مِنهُمْ ﴿فَإنَّك أنْت العَزِيز﴾ عَلى أمْره ﴿الحَكِيم﴾ فِي صُنْعه"],[119,119,"﴿قالَ اللَّه هَذا﴾ أيْ يَوْم القِيامَة ﴿يَوْم يَنْفَع الصّادِقِينَ﴾ فِي الدُّنْيا كَعِيسى ﴿صِدْقهمْ﴾ لِأَنَّهُ يَوْم الجَزاء ولا يَنْفَع الكاذِبِينَ فِي الدُّنْيا صِدْقهمْ فِيهِ كالكُفّارِ لِما يُؤْمِنُونَ عِنْد رُؤْيَة العَذاب ﴿لَهُمْ جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها أبَدًا رَضِيَ اللَّه عَنْهُمْ﴾ بِطاعَتِهِ ﴿ورَضُوا عَنْهُ﴾ بِثَوابِهِ ﴿ذَلِكَ الفَوْز العَظِيم﴾ ولا يَنْفَع الكاذِبِينَ فِي الدُّنْيا صِدْقهمْ فِيهِ كالكُفّارِ لَما يُؤْمِنُونَ عِنْد رُؤْيَة العَذاب"],[120,120,"﴿لِلَّهِ مُلْك السَّماوات والأَرْض﴾ خَزائِن المَطَر والنَّبات والرِّزْق وغَيْرها ﴿وما فِيهِنَّ﴾ أتى بِما تَغْلِيبًا لِغَيْرِ العاقِل ﴿وهُوَ عَلى كُلّ شَيْء قَدِير﴾ ومِنهُ إثابَة الصّادِق وتَعْذِيب الكاذِب، وخُصَّ العَقْل ذاته فَلَيْسَ عَلَيْها بِقادِرٍ"]]};
